// Sanjay Vaidhya Close-Up Interview Translations Database
// Supports English, Hindi, Gujarati, and Marathi translation

const interviewTranslations = {
  hi: {
    "sidebar-quote": `"हर पोर्ट्रेट के पीछे एक अनलिखी जीवनी होती है। मैं उनके चेहरे की तस्वीर नहीं लेता; मैं उनके साहित्य की तस्वीर लेता हूँ।"`,
    "intro-1": `उनका नाम गुजरात और भारत भर में कला प्रदर्शनियों में और कई फोटो-पुस्तकों तथा कॉफी-टेबल संस्करणों के कवर पर दिखाई देता है। फिर भी सार्वजनिक भाषा अक्सर उन छवियों के पीछे मौजूद व्यक्तित्व का वर्णन करने में कम रह जाती है - एक ऐसा फोटोग्राफर जो अपने लेंस के माध्यम से दृश्यों और चेहरों को जीवंत कर देता है, इस विधा का एक शांत उस्ताद, कैमरे का एक कवि: <strong>संजय वैद्य</strong>।`,
    "intro-2": `2007 से, उनकी विशिष्ट फोटो-पुस्तकें नियमित रूप से प्रकाशित हो रही हैं, विशेष रूप से प्रसिद्ध हस्तियों पर उनकी पोर्ट्रेट श्रृंखला। ये पुस्तकें अक्सर तस्वीरों के संग्रह से कम और उन हस्तियों के अंतरंग दृश्य संस्मरणों की तरह अधिक महसूस होती हैं जिन्हें वे कैद करती हैं। इन्होंने उन्हें व्यापक पहचान और भारत के अग्रणी फोटोग्राफरों में एक स्थान दिलाया है। 
    <br><br>
    अहमदाबाद में रहने वाले संजय द्वारा खींचे गए प्रसिद्ध हस्तियों में गुजराती साहित्य के दिग्गज जैसे <em>सुरेश दलाल, तारक मेहता, चंद्रकांत बख्शी और गुणवंत शाह</em>; भारतीय शास्त्रीय संगीत के उस्ताद जैसे <em>पंडित भीमसेन जोशी, पंडित जसराज, पंडित शिवकुमार शर्मा, उस्ताद अमजद अली खान, बेगम परवीन सुल्ताना, पंडित हरिप्रसाद चौरसिया, पंडित राजन-साजन मिश्रा, उस्ताद जाकिर हुसैन</em> और ग्रैमी विजेता <em>पंडित विश्व मोहन भट्ट</em>; आध्यात्मिक गुरु जैसे <em>मोरारी बापू, श्री श्री रविशंकर, प्रमुख स्वामी महाराज</em> और <em>रमेशभाई ओझा</em>; और प्रसिद्ध फिल्मी हस्तियां जैसे <em>गुलजार, अमिताभ बच्चन, ऐश्वर्या राय बच्चन, आशा भोंसले, मनोज वाजपेयी, तब्बू</em> और <em>इरफान खान</em> शामिल हैं।`,
    "intro-3": `अहमदाबाद में रहकर, संजय फोटोग्राफी सिखाते हैं, कार्यशालाएँ आयोजित करते हैं, और रचनात्मक दृश्य कहानी कहने की कला का अन्वेषण करते हैं। भाषा और साहित्य के प्रति उनके गहरे प्रेम ने उन्हें साहित्यिक प्रकाशन, संस्कृत लोक-संगीत फ्यूजन और प्रसिद्ध गुजराती लेखकों पर समृद्ध वृत्तचित्र बनाने की ओर आकर्षित किया है। जब उनसे एक साक्षात्कार के लिए पूछा गया, तो उन्होंने अपनी चिरपरिचित विनम्रता के साथ जवाब दिया: <em>“मैं बोलने में बहुत अच्छा नहीं हूँ,”</em> और फिर यह बातचीत शुरू हुई।`,
    
    "theme-1": `I. एक आह्वान की उत्पत्ति <span>शुरुआत और पेशा</span>`,
    "q1": `Q: संजय, फोटोग्राफी में यह असामान्य रुचि कहाँ से आई और इसका विकास कैसे हुआ?`,
    "a1": `A: फोटोग्राफी हमेशा से मेरा जुनून, मेरा शौक रही है। मैंने कभी नहीं सोचा था कि मैं इसे पेशेवर रूप से अपनाऊंगा। मुझे हमेशा प्रकृति से प्यार रहा है और मेरे आस-पास होने वाली हर चीज में मेरी दिलचस्पी रही है। युवावस्था में भी, मुझे लगता था कि भले ही मैं घटनाओं को होते हुए देख रहा था, लेकिन मैं पूरी तरह से उनके अंदर नहीं था। कहीं न कहीं, मैं उसमें शामिल होना चाहता था। मुझे लगता है कि मेरे भीतर हमेशा कुछ ऐसा था जो किसी क्षण को देखना और उसे थाम लेना चाहता था। जिस क्षण मैंने पहली बार कैमरा पकड़ा और पहली कुछ तस्वीरें खींचीं, मुझे पता था कि यही वह काम है जो मैं करना चाहता हूँ। चाहे मैं असम गया हूँ या कहीं और, मुझे किसी चीज़ को देखने, उसकी तस्वीर लेने और उसे वापस लाने की प्रक्रिया से प्यार था। उस पूरे अनुभव ने मुझे अपार आनंद दिया। इसी तरह मैंने इस क्षेत्र में कदम रखा।`,
    
    "q2": `Q: फोटोग्राफी को एक शौक के रूप में रखना एक बात है, लेकिन इसे एक पेशे के रूप में अपनाना क्या जोखिम भरा नहीं था? एक नए फोटोग्राफर के लिए इसका अर्थशास्त्र कैसे काम करता है?`,
    "a2": `A: यह निश्चित रूप से जोखिम भरा लगा। मेरे परिवार में, मेरी दादी कहा करती थीं, “कब तक ये फोटो खींचते रहोगे? अगर कोई शादी का प्रस्ताव लेकर आएगा और पूछेगा कि लड़का क्या करता है, तो हम क्या कहेंगे - कि वह तस्वीरें लेता है?” उन दिनों फोटोग्राफी को अक्सर एक छोटा काम माना जाता था। मैं कभी भी एक मेधावी छात्र नहीं था, और मेरा शैक्षणिक रिकॉर्ड काफी औसत था। इसलिए मेरी कभी डॉक्टर या इंजीनियर बनने की महत्वाकांक्षा नहीं थी। मैंने पहले फोटोग्राफी को एक शौक के रूप में लिया, और फिर, लगभग बिना महसूस किए, यह मेरा पेशा बन गया।
    <br><br>
    उन दिनों फोटोग्राफी का अर्थशास्त्र बहुत अलग था। पेंटिंग की तुलना में, फोटोग्राफी को एक निचला कला रूप माना जाता था - वास्तव में, कई लोग इसे कला भी नहीं मानते थे। इसे सौंदर्यशास्त्रीय के बजाय तकनीकी चीज के रूप में देखा जाता था। बाद में, डिजिटल तकनीक के आने से यह माध्यम पूरी तरह बदल गया। उससे पहले भी, फिल्म फोटोग्राफी और बाद में टेलीविजन और सिनेमा के माध्यम से, विशेष रूप से 1990 के दशक के बाद से, फोटोग्राफी को बड़ी पहचान मिली। इसका आर्थिक मूल्य भी बदला। आज, कोई कल्पना भी नहीं कर सकता कि फोटोग्राफर कितना पैसा कमा सकते हैं। भारत में, कई फोटोग्राफर अब फिल्मों या टेलीविजन धारावाहिकों के कैमरामैन से अधिक कमाते हैं।`,
    
    "pullquote-1": `"हर तस्वीर सेकंड के आठवें हिस्से में पैदा होती है।"`,
    
    "theme-2": `II. क्षणभंगुरता की कला <span>क्षण, पेंटिंग और प्रकाश</span>`,
    "q3": `Q: आप एक चित्रकार भी हैं। एक फोटोग्राफर द्वारा बनाई गई छवि और एक चित्रकार द्वारा बनाई गई छवि में क्या अंतर है?`,
    "a3": `A: चूंकि मैं एक फोटोग्राफर हूँ, मुझे यह नहीं कहना चाहिए कि फोटोग्राफी महान है। लेकिन ईमानदारी से कहूँ तो, मुझे हमेशा लगता है कि जब आप पेंटिंग करते हैं, तो आपको काम को बदलने की स्वतंत्रता होती है। यदि कुछ सही नहीं है, तो आप उसका आकार, रूप या रंग बदल सकते हैं। पेंटिंग में वह आजादी है। फोटोग्राफी में ऐसी कोई छूट नहीं है। आपको एक ही क्षण को कैद करना होता है और उसे थामे रखना होता है। यदि आप चूक गए, तो वह चला गया। इसलिए आपको सतर्क रहना होगा, क्षण के आने से पहले उसे भांपना होगा, और फिर सही समय पर क्लिक करना होगा। सलमान रुश्दी ने एक खूबसूरत बात कही थी: “हर तस्वीर सेकंड के आठवें हिस्से में पैदा होती है।” मैं इसे इसी तरह देखता हूँ। समय के उस छोटे से हिस्से में, आपको साबित करना होगा कि आपकी तस्वीर कितनी शक्तिशाली हो सकती है।`,
    
    "q4": `Q: आपने प्रकृति फोटोग्राफी से शुरुआत की थी, लेकिन आज आप एक पोर्ट्रेट फोटोग्राफर के रूप में जाने जाते हैं। यह यात्रा कैसे हुई?`,
    "a4": `A: शुरुआत में ज्यादा विकल्प नहीं थे। वन्यजीव, प्रकृति, कैंडिड या पोर्ट्रेट फोटोग्राफी के बीच वैसा कोई बड़ा अंतर नहीं था जैसा आज हम सोचते हैं। और गुजरात, या यहाँ तक कि अहमदाबाद में फोटोग्राफी सिखाने वाली कोई संस्था नहीं थी। मैंने गलतियों से सीखा। पहले एक कैमरा खरीदना पड़ता था, फिर फिल्म रोल, फिर तस्वीरें लेना, और फिर उन्हें किसी अनुभवी व्यक्ति को दिखाना - और अगर वह व्यक्ति अच्छे मूड में हुआ, तो शायद वह आपको एक-दो बातें सिखा देगा। मुख्य नियम सरल था: जो गलती आप पहले ही कर चुके हैं, उसे कभी न दोहराएं।
    <br><br>
    परिदृश्य अधिक आसानी से समझ आ जाते थे क्योंकि वे विविधता प्रदान करते थे - विभिन्न पेड़, विभिन्न झीलें, विभिन्न दृश्य। चेहरों की ओर मेरा झुकाव लगभग अनजाने में हुआ। मुझे नहीं लगता कि मैंने जानबूझकर पोर्ट्रेट की ओर बढ़ने का फैसला किया था। लेकिन जैसे-जैसे मैं आगे बढ़ा, मुझे एहसास हुआ कि इंसानी चेहरे भी वैसी ही विविधता प्रदान करते हैं जैसी परिदृश्य। मैं 40 साल से फोटोग्राफी कर रहा हूँ, और मैंने अभी तक दो ऐसे चेहरे नहीं देखे हैं जो बिल्कुल एक जैसे हों। यहाँ तक कि जुड़वां बच्चे भी मुझे नहीं लगते। इतने सारे चेहरों से गुजरना एक असाधारण अनुभव है।
    <br><br>
    हर चेहरा एक कहानी समेटे होता है, उसका अपना एक छिपा हुआ हस्ताक्षर होता है। उस कहानी को ढूंढना एक आनंद है। इसमें जोखिम है, लेकिन इसमें रोमांच और खुशी भी है। यदि आप किसी व्यक्ति के चेहरे के पीछे की कहानी को सामने ला सकते हैं, तो आप सफल हो गए हैं। अन्यथा, तस्वीर कितनी भी आकर्षक क्यों न हो, वह केवल सतही ही रहती है। एक पोर्ट्रेट में व्यक्ति का कुछ हिस्सा प्रकट होना चाहिए। इसलिए मैं विषय से पहले मिलना पसंद करता हूँ। भले ही मुझे अगले दिन किसी का शूट करना हो, मुझे पहले उनके साथ दो या तीन घंटे बिताना पसंद है - बस साधारण बातचीत, कुछ भी औपचारिक नहीं। उस समय के दौरान, मैं चेहरे को ध्यान से देखता हूँ। मैं व्यक्ति को, उनकी पसंद-नापसंद को देखता हूँ, और यह समझने की कोशिश करता हूँ कि चेहरे का कौन सा हिस्सा अधिक ईमानदारी से बात करता है। आँखों को मैंने बेहद सच्चा पाया है। और चूँकि हमारा काम एक लेंस से होता है, इसलिए हमें भी ईमानदार होना चाहिए।`,
    
    "q5": `Q: आप पोर्ट्रेट के लिए उन लोगों को कैसे चुनते हैं जिनकी आप तस्वीर खींचते हैं?`,
    "a5": `A: अब मेरे पास चुनने की काफी आजादी है। पहले मैं एक कमर्शियल फोटोग्राफर था, इसलिए जो भी पैसे देता था, मैं उसकी तस्वीर खींच लेता था। आज मैं मना कर सकता हूँ। मैं किसी से कह सकता हूँ कि मैं उनकी तस्वीर नहीं खींचना चाहता, या मुझे ऐसा करने में सहजता महसूस नहीं हो रही है। मैं किसी एंटीहीरो, किसी असामान्य या सनकी व्यक्ति की तस्वीर खींच सकता हूँ, लेकिन किसी खलनायक की नहीं। अगर मुझे लगता है कि कोई व्यक्ति मूल रूप से बनावटी है, तो मैं उसकी तस्वीर नहीं ले सकता। जब किसी चेहरे पर मुखौटा होता है, तो वह कृत्रिमता मुझे साफ दिखाई देती है, और मैं फोटोग्राफी के जरिए उस मुखौटे को नहीं हटा सकता। यह मुझे परेशान करता है। इसलिए मैं ऐसे लोगों की तस्वीर खींचना पसंद नहीं करता। बेशक, यह चीजों को देखने का मेरा निजी नज़रिया है। जिसे मैं बनावटी मानता हूँ, हो सकता है कि वह किसी दूसरे की नज़र में वैसा न हो।`,
    
    "pullquote-2": `"हर चेहरे में एक कहानी होती है, उसका अपना एक छिपा हुआ हस्ताक्षर। उस कहानी को खोजना एक आनंद है।"`,
    
    "theme-3": `III. मुठभेड़ और रहस्योद्घाटन <span>मोरारी बापू और अमरनाथ पर खतरा</span>`,
    "q6": `Q: आपने कई पोर्ट्रेट पुस्तकें बनाई हैं। किन हस्तियों के साथ काम करना सबसे दिलचस्प रहा है? कोई ऐसी यादें जो आपके मन में बसी हों?`,
    "a6": `A: मैं भाग्यशाली रहा हूँ कि मुझे विभिन्न क्षेत्रों के कई लोगों के साथ समय बिताने का मौका मिला, और अक्सर केवल कुछ घंटों के लिए नहीं बल्कि लगातार दो या तीन दिनों तक। अन्य सभी अनुभवों में से किसी एक को चुनना कठिन है। लेकिन एक स्मृति जो आज भी स्पष्ट है, वह मोरारी बापू की एक फोटो बुक पर काम करने के समय की है।
    <br><br>
    मैं उनकी तस्वीर लेने जगन्नाथ पुरी गया था। वहाँ का माहौल एकदम अलग था, संस्कृति अलग थी और मुझे कोई नहीं जानता था। बापू के आसपास इतने लोग थे कि मैं उनके पास नहीं जा सका। मैंने मान लिया कि उन्होंने मुझे पहचान लिया है और देखने पर मुझे बुलाएंगे, लेकिन उन तक पहुँचने के लिए कई बाधाओं को पार करना पड़ता था। इसलिए मैंने दो दिन तक इंतजार किया। तीसरे दिन, मैं आखिरकार अंदर घुसने में सफल रहा।
    <br><br>
    जब उन्होंने मुझे देखा, तो उन्होंने मुझे बुलाया और पूछा, “बेटा, तुम यहाँ कैसे पहुँचे?” मैंने उनसे कहा, “बापू, मैं आपकी तस्वीर लेने आया हूँ। मैं एक फोटो बुक बना रहा हूँ, और मैं सुबह से शाम तक आपके साथ रहना चाहता हूँ।” उस समय वे पचास या साठ लोगों से घिरे हुए थे, और उन सभी ने मुझे उनके पैर न छूने और उनसे इतनी सहजता से बात करने के लिए डांटा। लेकिन मैं उन्हें बचपन से जानता था। मुझे ऐसा कोई अहसास नहीं था कि औपचारिक इशारे जरूरी थे। वे मुझसे बड़े हैं, बिल्कुल, और मैं बड़ों का सम्मान करता हूँ। यह हमारी संस्कृति का हिस्सा है। लेकिन मुझे ऐसा नहीं लगता कि सिर्फ इसलिए कि कोई आध्यात्मिक गुरु है, मुझे अचानक खुद को साष्टांग प्रणाम करना होगा। मैं गलत हो सकता हूँ, लेकिन मैंने जिन आध्यात्मिक गुरुओं की तस्वीर खींची है, उनमें से किसी ने भी इस पर आपत्ति नहीं की। चाहे वे मोरारी बापू हों, रमेशभाई ओझा हों, या श्री श्री रविशंकर हों, उनमें से किसी ने भी कभी नहीं पूछा कि मैं उनके चरणों में क्यों नहीं झुका।
    <br><br>
    अगले दिन, जब मुझे फिर से चार बजे बुलाया गया, तो हल्की बूंदाबांदी हो रही थी। जब मैं बापू के कमरे में गया, तो पूरा प्रांगण और सीढ़ियाँ खचाखच भरी थीं। वहाँ लोग मेरी आलोचना कर रहे थे कि मेरे जैसे व्यक्ति को किसी संत को परेशान नहीं करना चाहिए या उनकी साधना में बाधा नहीं डालनी चाहिए। एक पल के लिए मैंने सोचा भी कि क्या मैं कुछ गलत कर रहा हूँ। लेकिन जैसे ही मैं उनसे मिला, वह संदेह गायब हो गया। उन्होंने बस मुझसे कहा, “मैं अपना काम कर रहा हूँ, तुम अपना करो।” फिर उन्होंने अपनी दिनचर्या जारी रखी - सूर्य को जल देना, तुलसी के पौधे को सींचना - और मुझे हर चीज़ की खूबसूरत तस्वीर लेने की अनुमति दी। पच्चीस मिनट के भीतर मैंने लगभग एक सौ पचास तस्वीरें ले लीं। उन्होंने बिल्कुल भी विरोध नहीं किया।`,
    
    "q7": `Q: आपको कठिन परिस्थितियों का भी सामना करना पड़ा होगा।`,
    "a7": `A: हाँ, निश्चित रूप से। मुझे सही साल याद नहीं है, लेकिन मुझे लगता है कि यह 1998 था जब अमरनाथ में भूस्खलन हुआ था और चार या पांच हजार लोग मारे गए थे। मैं उस समय मुंबई में था, और मुझे वहाँ जाकर तस्वीरें लेने का काम सौंपा गया था। मुख्य संपादक हरकिशन मेहता ने मुझे बुलाया - एक ऐसे व्यक्ति जिनका मैं बहुत सम्मान करता हूँ - और मुझसे कहा कि मुझे जाना होगा क्योंकि बाकी सभी मना कर रहे थे। उन्हें लगा कि यह बहुत कठिन है। उन्होंने पूछा कि क्या मैं जाऊँगा। मैं छोटा था, इसलिए मैं उत्साहित था। अगर बाकी सब ना कह रहे थे, तो इसने मुझे और भी आकर्षित किया। इसलिए मैं चला गया।
    <br><br>
    मुंबई से मैं अहमदाबाद गया, फिर दिल्ली, फिर श्रीनगर। श्रीनगर से सेना हमें हेलीकॉप्टर से शेषनाग ले गई। वहाँ कुछ विदेशी पत्रकार भी थे, लेकिन चूँकि मैं भारतीय था, इसलिए मुझे हेलीकॉप्टर से यात्रा करने का पहला अवसर दिया गया। मैं बहुत खुश था, यह सोचकर कि यह इतनी बड़ी खबर को कवर करने का कितना शानदार मौका है। लेकिन जब मैं उतरा और अपने आसपास का नजारा देखा, तो वह बेहद डरावना था। तस्वीरें लेते समय मैं कांप रहा था - ठंड से नहीं, बल्कि जो मैं देख रहा था उसके खौफ से।
    <br><br>
    वापसी में हेलीकॉप्टर में पायलट, एक अन्य व्यक्ति और मैं थे। फिर उन्होंने उसमें शव लोड किए। करीब बीस शवों को एक के ऊपर एक लादा गया था। हेलीकॉप्टर के उड़ान भरते समय मुझे उनके सहारे खड़ा होना पड़ा और फिर खिड़की से हवाई शॉट लेने पड़े। आज भी जब मैं उन पलों को याद करता हूँ, तो मेरे अंदर एक सिहरन पैदा हो जाती है। अपने आसपास बीस शवों का होना, किसी का हाथ अपने पैर से छूता हुआ महसूस करना, और फिर भी तटस्थ रहकर एक न्यूट्रल आब्जर्वर की तरह उस दृश्य की तस्वीर लेना - यह आसान नहीं है। आप यह नहीं सोच सकते कि यह किसका रिश्तेदार है, या उनके परिवार को शव मिलेगा या नहीं। आप केवल अपना काम कर सकते हैं। वे तीन या चार दिन अविस्मरणीय रहेंगे।`,
    
    "pullquote-3": `"अपने आसपास बीस शवों का होना, और फिर भी तटस्थ रहकर एक न्यूट्रल आब्जर्वर की तरह उस दृश्य की तस्वीर लेना - यह आसान नहीं है।"`,
    
    "theme-4": `IV. प्रकाश का दर्शन <span>अहंकार, विज्ञान और डिजिटल युग</span>`,
    "q8": `Q: फोटोग्राफी कला और विज्ञान दोनों है। आप इसे कैसे देखते हैं?`,
    "a8": `A: मैं एक औसत छात्र था, और विज्ञान कभी भी मेरे दिमाग में नहीं रहा। इसलिए मेरे पास फोटोग्राफी को एक कला के रूप में देखने के अलावा कोई विकल्प नहीं है। और यह एक अद्भुत कला है। इसके माध्यम से मैंने बहुत कुछ हासिल किया है - सामाजिक रूप से, आर्थिक रूप से, और शायद सबसे महत्वपूर्ण, व्यक्तिगत विकास के संदर्भ में। फोटोग्राफी ने मुझे कमल की तरह अनासक्त होकर काम करना सिखाया है। इसने मुझे सिखाया है कि मैं जो हूँ वही रहूँ।
    <br><br>
    पहले, जब मैं एक खूबसूरत सूर्योदय, सूर्यास्त या परिदृश्य की तस्वीर लेकर वापस आता था, तो मुझे एक निश्चित गर्व महसूस होता था - कि मैंने कुछ असाधारण बनाया है, कि मेरे पास महान कलात्मक क्षमता है। लेकिन बाद में मुझे एहसास हुआ कि कोई भी खूबसूरत सूर्योदय या सूर्यास्त की तस्वीर ले सकता है। इसमें कोई बड़ी बहादुरी नहीं है। मेरा सौभाग्य इस बात में है कि मुझे वहाँ रहने का अवसर दिया गया। मैं असम, हिमालय गया हूँ, ऐसी जगहों पर जहाँ बहुत से लोग नहीं पहुँच सकते।
    <br><br>
    जो तस्वीरें मैं वापस लाता हूँ वे केवल एक माध्यम हैं। उस अर्थ में, मैं केवल एक डाकिया हूँ, और एक डाकिया के पास पत्र ले जाने के बारे में कोई अहंकार नहीं होता। एक फोटोग्राफर के रूप में, मैं केवल एक माध्यम हूँ। सूर्योदय और सूर्यास्त अपने आप में शानदार हैं। उस अहसास ने मेरे भीतर के दर्शक को मजबूत किया। एक बार जो भी अहंकार मेरे अंदर आया होगा, वह धीरे-धीरे गायब हो गया। आज भी, जब मेरे छात्र - सोलह या सत्रह साल के लड़के-लड़कियां - मुझे अपनी तस्वीरें लाकर दिखाते हैं, तो मुझे वही जिज्ञासा और आश्चर्य महसूस होता है जो वे महसूस करते हैं। वह विस्मय की भावना मुझे कभी छोड़कर नहीं गई।`,
    
    "q9": `Q: क्या तकनीक ने फोटोग्राफी को इतना आसान बना दिया है कि अब कोई भी अच्छी तस्वीर ले सकता है?`,
    "a9": `A: हाँ, और यह बहुत सच है। आज के डिजिटल युग में, एक खराब तस्वीर लेने के लिए लगभग कड़ी मेहनत करनी पड़ती है। कैमरे इतने उन्नत हैं कि तस्वीरें अक्सर अपने आप अच्छी आती हैं। तकनीक ने पूरे माध्यम को बदल दिया। पहले फिल्म होती थी, और फिल्म के साथ अलग-अलग स्पीड, लोडिंग, शूटिंग, डेवलपिंग और आखिरकार प्रिंट की गई तस्वीर को हाथ में पकड़ना आता था। डिजिटल तकनीक के साथ वह सब गायब हो गया।
    <br><br>
    पहला बदलाव यह था कि फोटोग्राफी सस्ती हो गई। 1989 या 1990 में, यदि आप छत्तीस फ्रेम का रोल शूट करते थे, तो प्रिंट वापस आने तक आप आसानी से सात या आठ सौ रुपये खर्च कर चुके होते थे। फोटोग्राफी के एक छात्र के लिए, वह बहुत पैसा था। आज आप अपनी तस्वीरें तुरंत कंप्यूटर पर देख सकते हैं, इसलिए यह प्रक्रिया आसान और कम खर्चीली दोनों है। नए तरह के लेंसों ने भी काम को सरल बना दिया। फिर इंटरनेट आया, और तस्वीरें भेजना आसान हो गया। मैं आपको कुछ ही सेकंड में एक छवि भेज सकता हूँ।
    <br><br>
    तो फोटोग्राफी फोटोग्राफरों के लिए आसान हो गई है, लेकिन साथ ही, अपनी गुणवत्ता साबित करना बहुत कठिन हो गया है क्योंकि प्रतिस्पर्धा बहुत तीव्र है। आज लगभग कोई भी अच्छी फोटो ले सकता है। बहुत से लोग फेसबुक, इंस्टाग्राम और कई अन्य प्लेटफार्मों पर आकर्षक तस्वीरें पोस्ट कर सकते हैं। "अच्छे फोटोग्राफर" का एकाधिकार अब समाप्त हो गया है। आपको हर दिन खुद को साबित करना होगा।`,
    
    "q10": `Q: क्या विज्ञान की प्रगति से कला की धीमी मृत्यु हुई है?`,
    "a10": `A: नहीं, मैं इससे सहमत नहीं हूँ। अंत में, यह गुजराती कहावत की तरह है: “यदि कुएं में पानी है, तो वह नाली तक पहुंचेगा।” दूसरे शब्दों में, यदि मूल तस्वीर शक्तिशाली है, तभी संपादन उसका समर्थन कर सकता है। यदि आधार छवि कमजोर है, तो कुछ भी वास्तव में उसे नहीं बचा सकता। फोटोशॉप और अन्य संपादन उपकरण केवल सहायक उपकरण हैं - जैसे आभूषण, जैसे मेकअप।
    <br><br>
    एक दुल्हन खूबसूरती से सजी हो सकती है, भारी मेकअप और आभूषणों से लदी हो सकती है, लेकिन उसका अपना प्राकृतिक सौंदर्य सबसे अधिक मायने रखता है। यदि वह पहले से ही सुंदर है, तो वह बिना मेकअप के भी प्यारी लगेगी। बिना मेकअप का चेहरा भी एक खूबसूरत चेहरा हो सकता है।`,
    
    "pullquote-4": `"एक डाकिया के पास पत्र ले जाने के बारे में कोई अहंकार नहीं होता। एक फोटोग्राफर के रूप में, मैं केवल एक माध्यम हूँ।"`,
    
    "theme-5": `V. मशाल सौंपना <span>शिक्षण, संगीत और रचनात्मक प्रयास</span>`,
    "q11": `Q: आप फोटोग्राफी सिखाने और कार्यशालाएँ आयोजित करने में शामिल हैं। इस कला को वास्तव में कहाँ तक सिखाया जा सकता है?`,
    "a11": `A: अब यह काफी बेहतर है। हमारे समय में, फोटोग्राफी सिखाने वाली कोई संस्था नहीं थी। आज कई कॉलेज और संस्थान ऐसा करते हैं। और नए उपकरणों के साथ, पढ़ाना भी आसान हो गया है। लेकिन मुझे हमेशा लगा है कि फोटोग्राफी कभी भी बंद कमरों या सिर्फ कक्षाओं में नहीं सीखी जा सकती। मैं कॉलेजों में पढ़ाता हूँ, लेकिन पहली तीन या चार परिचयात्मक कक्षाओं के बाद, मैं आमतौर पर छात्रों को बाहर ले जाता हूँ। हम पांडिचेरी, असम और हिमालय जैसी जगहों पर जाते हैं और वहाँ कार्यशालाएँ आयोजित करते हैं।
    <br><br>
    मेरा व्यक्तिगत मानना है कि छात्रों को कई गलतियाँ करने की अनुमति दी जानी चाहिए। मैं उनसे कहता हूँ कि वे खूब गलतियाँ करें और उनसे सीखें। लैंडस्केप फोटोग्राफी एक ऐसा क्षेत्र है जहाँ गलतियाँ तुरंत दिखाई देती हैं। गलती परिदृश्य में नहीं होती, बल्कि इस बात में होती है कि आप इसे कैसे कैद करते हैं। यदि आप इसे सही तरीके से नहीं करते हैं, तो त्रुटि दिखाई देने लगती है। इसी तरह कोई सीखता है - अपनी गलतियों को स्पष्ट रूप से देखकर। मेरा मानना है कि हर व्यक्ति के भीतर एक फोटोग्राफर होता है। असली सवाल यह है कि आप उस आंतरिक फोटोग्राफर को कितना अवसर देते हैं।`,
    
    "q12": `Q: संजय, फोटोग्राफी के अलावा आपकी और क्या रुचियां हैं?`,
    "a12": `A: मुझे पढ़ना बहुत पसंद है। मेरे लिए पढ़ना सांस लेने जैसा है। मुझे बस पढ़ना ही है। मुझे अच्छा संगीत भी बहुत पसंद है। बिना पढ़ने और संगीत के मेरा काम नहीं चल सकता। मुझे दोनों का बहुत शौक है, और शायद यही कारण है कि मैं बहुत अच्छा लेखक या संगीतकार नहीं बन पाया - क्योंकि मैं किताबों और संगीत का पूर्णकालिक प्रेमी हूँ। मैं सब कुछ पढ़ता हूँ: कथा साहित्य, गैर-कथा साहित्य, निबंध, पत्र, कविता - सब कुछ। और मैं सभी भाषाओं में पढ़ता हूँ।
    <br><br>
    संगीत में, मैं भारतीय शास्त्रीय संगीत पसंद करता हूँ, हालाँकि मुझे किसी रॉक बैंड से कोई आपत्ति नहीं है। मैं रॉक का भी आनंद लेता हूँ, जितना मैं समझ सकता हूँ। मेरा बेटा रॉक और जैज़ बैंड से जुड़ा है, और मुझे बहुत अच्छा लगता है जब वह मुझे चीजें समझाता है, सिखाता है और दिखाता है कि यह कैसे काम करता है। मैं संगीत के हर रूप की सराहना करता हूँ, लेकिन भारतीय शास्त्रीय संगीत मुझे थोड़ा अधिक आकर्षित करता है क्योंकि मैं इसे बेहतर समझता हूँ।`,
    
    "q13": `Q: आपने हमारे कई महान संगीतकारों की तस्वीरें खींची हैं। वह अनुभव कैसा था?`,
    "a13": `A: हाँ, मैंने लगभग सभी प्रमुख भारतीय शास्त्रीय संगीतकारों की तस्वीरें खींची हैं। लेकिन सच कहूँ तो, मुझे हमेशा अपने भीतर एक खालीपन महसूस होता था क्योंकि मैं संगीत नहीं जानता था। मैंने कलाकारों के सर्वोत्तम क्षणों को कैद करके - उनकी बेहतरीन तस्वीरों के माध्यम से उस कमी को पूरा करने की कोशिश की।
    <br><br>
    एक तरह से, मैं अपने काम को यथासंभव सावधानीपूर्वक और खूबसूरती से करके उस कमी की भरपाई करना चाहता था। चूंकि मैं संगीत नहीं जानता, इसलिए मुझे लगता है कि मुझे कुछ ऐसा करना चाहिए जिससे संगीतकार मुझे याद रखें। सो जब पंडित शिवकुमार शर्मा या उस्ताद जाकिर हुसैन जैसे दिग्गज मुझे फोन करते हैं और कहते हैं, “तस्वीर बहुत अच्छी आई है - कृपया इसे हमें दें,” तो मुझे ऐसा लगता है जैसे मैंने कोई खूबसूरत राग सीख लिया हो।`,
    
    "q14": `Q: संजय, यदि आप आज एक प्रसिद्ध फोटोग्राफर नहीं होते, तो आपको क्या लगता है कि आप क्या बनते?`,
    "a14": `A: मुझे लगता है कि मैं एक शिक्षक होता। ऐसा मैं इसलिए महसूस करता हूँ क्योंकि पिछले कई सालों से मैं पहले से ही शिक्षण में हूँ। एक शिक्षक होना, एक मार्गदर्शक होना - विशेष रूप से अब, जब मैं 60 के करीब पहुँच रहा हूँ - इतना संतोषजनक लगता है कि मेरा मानना है कि अगर मैं तस्वीरें नहीं ले रहा होता, तो मैं निश्चित रूप से एक शिक्षक बन जाता।
    <br><br>
    मुझे छात्रों के साथ रहना और उनकी ताजगी, उनकी ऊर्जा बहुत पसंद है। हमारे एक वरिष्ठ संकाय सदस्य, क्रिस्टोफर बेनिंगर - एक अमेरिकी वास्तुकार जो कई वर्षों तक भारत में रहे - ने एक बार हमें एक बहुत ही खूबसूरत बात सिखाई थी: “सबसे बड़ा उपहार जो आप अपने छात्र को दे सकते हैं वह है उसे हमेशा एक छात्र बने रहना सिखाना।” वह पंक्ति मेरे साथ रही है। यह गहराई से प्रेरणादायक और तरोताजा करने वाला लगता है। जब मैं पढ़ाने जाता हूँ, तो दो या तीन घंटे बाद थका हुआ नहीं लौटता। मैं खुद दो नई चीजें सीखकर, नई ऊर्जा के साथ वापस आता हूँ। और यही मुझे आगे बढ़ाता रहता है।`,
    
    "pullquote-5": `"सबसे बड़ा उपहार जो आप अपने छात्र को दे सकते हैं वह है उसे हमेशा एक छात्र बने रहना सिखाना।"`,
  },
  
  gu: {
    "sidebar-quote": `"દરેક પોટ્રેટ પાછળ એક અલિખિત આત્મકથા હોય છે. હું તેમના ચહેરાના ફોટા નથી પાડતો; હું તેમના સાહિત્યના ફોટા પાડું છું."`,
    "intro-1": `તેમનું નામ ગુજરાત અને ભારતભરમાં કલા પ્રદર્શનોમાં તેમજ અનેક ફોટો-પુસ્તકો અને કોફી-ટેબલ વોલ્યુમોના કવર પર અંકિત જોવા મળે છે. તેમ છતાં, જાહેર ભાષા ઘણીવાર આ છબીઓ પાછળના જીવંત વ્યક્તિત્વને વ્યક્ત કરવામાં ટૂંકી પડે છે - એક એવો ફોટોગ્રાફર જે પોતાના લેન્સ દ્વારા દ્રશ્યો અને ચહેરાઓને બોલતા કરે છે, પોતાની કલાના શાંત સ્વામી, કેમેરાના કવિ: <strong>સંજય વૈદ્ય</strong>.`,
    "intro-2": `૨૦૦૭ થી, તેમના વિશિષ્ટ ફોટો-પુસ્તકો નિયમિતપણે પ્રકાશિત થાય છે, ખાસ કરીને સેલિબ્રિટીઓ પરની તેમની પોટ્રેટ શ્રેણી. આ પુસ્તકો ઘણીવાર ફોટોગ્રાફ્સના સંગ્રહ કરતાં વધુ તે વ્યક્તિઓના આત્મીય દ્રશ્ય સંસ્મરણો જેવા લાગે છે. આ પુસ્તકોએ તેમને વ્યાપક ઓળખ અને ભારતના અગ્રણી ફોટોગ્રાફરોમાં સ્થાન અપાવ્યું છે. 
    <br><br>
    તેમણે ફોટોગ્રાફ કરેલી અસંખ્ય સુપ્રસિદ્ધ વ્યક્તિઓમાં ગુજરાતી સાહિત્યના મહારથીઓ જેવા કે <em>સુરેશ દલાલ, તારક મહેતા, ચંદ્રકાન્ત બક્ષી અને ગુણવંત શાહ</em>; ભારતીય શાસ્ત્રીય સંગીતના દિગ્ગજો જેવા કે <em>પંડિત ભીમસેન જોશી, પંડિત જસરાજ, પંડિત શિવકુમાર શર્મા, ઉસ્તાદ અમજદ અલી ખાન, બેગમ પરવીન સુલતાના, પંડિત હરિપ્રસાદ ચૌરસિયા, પંડિત રાજન-સાજન મિશ્રા, ઉસ્તાદ ઝાકિર હુસૈન</em> અને ગ્રેમી વિજેતા <em>પંડિત વિશ્વ મોહન ભટ્ટ</em>; આધ્યાત્મિક નેતાઓ જેવા કે <em>મોરારી બાપુ, શ્રી શ્રી રવિશંકર, પ્રમુખસ્વામી મહારાજ</em> અને <em>રમેશભાઈ ઓઝા</em>; તેમજ ફિલ્મ જગતના દિગ્ગજો જેવા કે <em>ગુલઝાર, અમિતાભ બચ્ચન, ઐશ્વર્યા રાય બચ્ચન, આશા ભોંસલે, મનોજ બાજપેયી, તબુ</em> અને <em>ઇરફાન ખાન</em> સામેલ છે.`,
    "intro-3": `અમદાવાદમાં સ્થિત સંજય ફોટોગ્રાફી શીખવે છે, વર્કશોપનું આયોજન કરે છે અને સર્જનાત્મક વિઝ્યુઅલ સ્ટોરીટેલિંગની શોધ કરે છે. સાહિત્ય અને ભાષા પ્રત્યેના તેમના ઊંડા પ્રેમે તેમને સાહિત્યિક પ્રકાશન, સંસ્કૃત લોક-સંગીત ફ્યુઝન અને અગ્રણી ગુજરાતી લેખકો પર દસ્તાવેજી ચિત્રો બનાવવા તરફ આકર્ષિત કર્યા છે. જ્યારે તેમને ઇન્ટરવ્યુ માટે પૂછવામાં આવ્યું ત્યારે તેમણે પોતાની સહજ નમ્રતાથી જવાબ આપ્યો: <em>“હું બોલવામાં બહુ સારો નથી,”</em> અને પછી આ સંવાદની શરૂઆત થઈ.`,
    
    "theme-1": `I. એક આહ્વાનનો પ્રારંભ <span>શરૂઆત અને વ્યવસાય</span>`,
    "q1": `Q: સંજય, ફોટોગ્રાફીમાં આ અસાધારણ રસ ક્યાંથી આવ્યો અને તેનો વિકાસ કેવી રીતે થયો?`,
    "a1": `A: ફોટોગ્રાફી હંમેશા મારો જુસ્સો, મારો શોખ રહ્યો છે. મેં ક્યારેય કલ્પના નહોતી કરી કે હું તેને વ્યવસાય તરીકે અપનાવીશ. મને હંમેશા પ્રકૃતિ પ્રત્યે પ્રેમ રહ્યો છે અને મારી આસપાસ બનતી દરેક વસ્તુમાં રસ પડતો હતો. યુવાનીમાં પણ મને લાગતું કે ભલે હું ઘટનાઓને બનતી જોતો હતો, પણ હું સંપૂર્ણપણે તેની અંદર નહોતો. ક્યાંક ને ક્યાંક હું તેમાં સામેલ થવા માંગતો હતો. મને લાગે છે કે મારામાં હંમેશાં કંઈક એવું હતું જે કોઈ ક્ષણને જોવા અને તેને કેમેરામાં કેદ કરવા ઈચ્છતું હતું. જે ક્ષણે મેં પહેલીવાર કેમેરો હાથમાં લીધો અને પહેલા થોડા ફોટા પાડ્યા, ત્યારે જ મને સમજાઈ ગયું કે આ જ મારે કરવું છે. હું અસમ ગયો હોઉં કે બીજે ક્યાંય, મને કોઈ વસ્તુ જોવાની, તેને કેમેરામાં કંડારવાની અને તેને પાછા લાવવાની પ્રક્રિયા ખૂબ ગમતી. તે આખા અનુભવે મને અપાર આનંદ આપ્યો. આ રીતે મેં આ ક્ષેત્રમાં પ્રવેશ કર્યો.`,
    
    "q2": `Q: શોખ તરીકે ફોટોગ્રાફી એ એક અલગ બાબત છે, પણ તેને વ્યવસાય તરીકે અપનાવવામાં શું જોખમ નહોતું? એક નવા ફોટોગ્રાફર માટે તેનું આર્થિક પાસું કેવી રીતે કામ કરે છે?`,
    "a2": `A: જોખમ તો ચોક્કસ હતું જ. મારા પરિવારમાં મારી દાદી કહેતા, “ક્યાં સુધી તું આ ફોટા પાડવાનું ચાલુ રાખીશ? જો કોઈ લગ્નનો પ્રસ્તાવ લઈને આવે અને પૂછે કે છોકરો શું કરે છે, તો અમે શું કહીશું - કે તે ફોટા પાડે છે?” તે દિવસોમાં ફોટોગ્રાફીને ઘણીવાર સામાન્ય વ્યવસાય ગણવામાં આવતો. હું ક્યારેય તેજસ્વી વિદ્યાર્થી નહોતો અને મારો શૈક્ષણિક રેકોર્ડ પણ સરેરાશ હતો. તેથી મારી ક્યારેય ડોક્ટર કે એન્જિનિયર બનવાની મહત્વાકાંક્ષા નહોતી. મેં પહેલા શોખ તરીકે ફોટોગ્રાફી શરૂ કરી, અને પછી ક્યારે તે maરો વ્યવસાય બની ગઈ તેની મને ખબર જ ન પડી.
    <br><br>
    તે દિવસોમાં ફોટોગ્રાફીનું આર્થિક પાસું ઘણું અલગ હતું. ચિત્રકલાની સરખામણીમાં, ફોટોગ્રાફીને નીચી કક્ષાની કલા ગણવામાં આવતી હતી - ખરેખર તો ઘણા લોકો તેને કલા પણ માનતા નહોતા. તેને કલાત્મક કરતાં તકનીકી બાબત તરીકે વધુ જોવામાં આવતી. પાછળથી ડિજિટલ ટેક્નોલોજીના આગમન સાથે આ માધ્યમમાં ધરમૂળથી બદલાવ આવ્યો. તે પહેલાં પણ, ફિલ્મ ફોટોગ્રાફી અને પાછળથી ટેલિવિઝન અને સિનેમા દ્વારા, ખાસ કરીને ૧૯૯૦ના દાયકા પછી, ફોટોગ્રાફીને વધુ માન્યતા મળી. તેની આર્થિક કિંમત પણ બદલાઈ ગઈ. આજે કોઈ કલ્પના પણ ન કરી શકે કે ફોટોગ્રાફરો કેટલા પૈસા કમાઈ શકે છે. ભારતમાં ઘણા ફોટોગ્રાફરો હવે ફિલ્મો કે ટેલિવિઝન સિરિયલના કેમેરામેન કરતાં વધુ કમાણી કરે છે.`,
    
    "pullquote-1": `"દરેક ફોટોગ્રાફ સેકન્ડના આઠમા ભાગમાં જન્મે છે."`,
    
    "theme-2": `II. તત્ક્ષણની કલા <span>ક્ષણો, ચિત્રકલા અને પ્રકાશ</span>`,
    "q3": `Q: તમે એક ચિત્રકાર પણ છો. ફોટોગ્રાફર દ્વારા બનાવેલી છબી અને ચિત્રકાર દ્વારા બનાવેલી છબી વચ્ચે શું તફાવત છે?`,
    "a3": `A: હું ફોટોગ્રાફર છું એટલે મારે એવું ન કહેવું જોઈએ કે ફોટોગ્રાફી વધુ મહાન છે. પરંતુ પ્રામાણિકપણે કહું તો, મને હંમેશા લાગ્યું છે કે જ્યારે તમે ચિત્ર દોરો છો, ત્યારે તમને કામમાં ફેરફાર કરવાની સ્વતંત્રતા હોય છે. જો કંઈક બરાબર ન હોય તો તમે તેનો આકાર, સ્વરૂપ અને રંગ બદલી શકો છો. તે સ્વતંત્રતા ચિત્રકલામાં છે. ફોટોગ્રાફીમાં એવી કોઈ સ્વતંત્રતા નથી. તમારે એક જ ક્ષણને પકડવી પડે છે અને તેને કેદ કરવી પડે છે. જો તમે તે ચૂકી ગયા, તો તે હંમેશ માટે ગઈ. તેથી તમારે સતર્ક રહેવું પડશે, ક્ષણ આવે તે પહેલાં તેનો અહેસાસ કરવો પડશે અને પછી યોગ્ય ક્ષણે ક્લિક કરવું પડશે. સલમાન રશ્દીએ એક સુંદર વાક્ય કહ્યું હતું: “દરેક ફોટોગ્રાફ સેકન્ડના આઠમા ભાગમાં જન્મે છે.” હું તેને આ જ રીતે જોઉં છું. સમયના એ સૂક્ષ્મ ભાગમાં, તમારે સાબિત કરવું પડશે કે તમારો ફોટો કેટલો શક્તિશાળી હોઈ શકે છે.`,
    
    "q4": `Q: તમે કુદરતી ફોટોગ્રાફીથી શરૂઆત કરી હતી, પરંતુ આજે તમે પોટ્રેટ ફોટોગ્રાફર તરીકે ઓળખાવ છો. આ સફર કેવી રીતે થઈ?`,
    "a4": `A: શરૂઆતમાં બહુ વિકલ્પો નહોતા. વન્યજીવન, પ્રકૃતિ, કેન્ડિડ કે પોટ્રેટ ફોટોગ્રાફી વચ્ચે એવો મોટો ભેદ નહોતો જેવો આજે આપણે વિચારીએ છીએ. અને ગુજરાત કે અમદાવાદમાં પણ ફોટોગ્રાફી શીખવતી કોઈ સંસ્થાઓ નહોતી. હું જાતે જ ભૂલો કરીને શીખ્યો. પહેલાં કેમેરો ખરીદવો પડતો, પછી ફિલ્મ રોલ, પછી ફોટા પાડવાના, અને પછી કોઈ અનુભવીને બતાવવાના - અને જો તે વ્યક્તિ સારા મૂડમાં હોય તો કદાચ તમને એકાદ-બે વાતો શીખવે. મુખ્ય નિયમ સરળ હતો: જે ભૂલ તમે એકવાર કરી હોય તે ક્યારેય ફરી ન કરવી.
    <br><br>
    કુદરતી દ્રશ્યો વધુ સરળતાથી કેપ્ચર કરી શકાતા કારણ કે તેમાં વિવિધતા હતી - જુદા જુદા વૃક્ષો, જુદા તળાવો, જુદા દ્રશ્યો. ચહેરાઓ તરફ મારું વલણ અજાણતાં જ બદલાયું. મને નથી લાગતું કે મેં જાણીજોઈને પોટ્રેટ તરફ વળવાનો નિર્ણય કર્યો હતો. પણ જેમ જેમ હું આગળ વધતો ગયો તેમ તેમ મને સમજાયું કે માનવ ચહેરા પણ કુદરતી દ્રશ્યો જેવી જ વિવિધતા આપે છે. હું 40 વર્ષથી ફોટોગ્રાફી કરું છું, છતાં મેં ક્યારેય બે સમાન ચહેરા જોયા નથી. જોડકાં બાળકો પણ મને સરખા નથી લાગતા. આટલા બધા ચહેરાઓનો અભ્યાસ કરવો એ એક અસાધારણ અનુભવ છે.
    <br><br>
    દરેક ચહેરો એક વાર્તા વહન કરે છે, પોતાની આગવી સહી ધરાવે છે. તે વાર્તા શોધવી એ એક આનંદ છે. તેમાં જોખમ છે, પણ સાથે ઉત્તેજના અને આનંદ પણ છે. જો તમે વ્યક્તિના ચહેરા પાછળની વાર્તા ઉજાગર કરી શકો, તો તમે સફળ છો. બાકી, ફોટો ભલે ગમે તેટલો આકર્ષક હોય, તે માત્ર ઉપરછલ્લો જ રહે છે. પોટ્રેટમાં વ્યક્તિનું વ્યક્તિત્વ છતું થવું જોઈએ. એટલે જ હું જે તે વ્યક્તિને અગાઉથી મળવાનું પસંદ કરું છું. બીજા દિવસે મારે કોઈનો ફોટો પાડવાનો હોય તો પણ હું પહેલાં તેમની સાથે બે-ત્રણ કલાક ગાળવાનું પસંદ કરું છું - સામાન્ય વાતચીત, કશું ઔપચારિક નહીં. તે સમય દરમિયાન હું ચહેરાને ધ્યાનપૂર્વક જોઉં છું. હું તે વ્યક્તિને, તેમની પસંદ-નાપસંદને જોઉં છું અને એ સમજવાનો પ્રયત્ન કરું છું કે ચહેરાની કઈ બાજુ વધુ પ્રામાણિકતા વ્યક્ત કરે છે. આંખોને મેં અતિશય સત્યવાદી અનુભવી છે. અને આપણું કામ લેન્સનું હોવાથી આપણે પણ પ્રામાણિક રહેવું પડે છે.`,
    
    "q5": `Q: પોટ્રેટ માટે તમે જે વ્યક્તિઓના ફોટા પાડો છો તેમની પસંદગી કેવી રીતે કરો છો?`,
    "a5": `A: હવે મારી પાસે પસંદગી કરવાની પૂરતી સ્વતંત્રતા છે. પહેલાં હું કોમર્શિયલ ફોટોગ્રાફર હતો, તેથી જે પણ પૈસા ચૂકવતું તેનો ફોટો પાડી લેતો. આજે હું ના પાડી શકું છું. હું કોઈને કહી શકું છું કે મારે તેમનો ફોટો નથી પાડવો અથવા મને તેમ કરવામાં કમ્ફર્ટેબલ નથી લાગતું. હું કોઈ એન્ટીહીરો, કોઈ અસાધારણ કે વિચિત્ર વ્યક્તિનો ફોટો પાડી શકું, પણ કોઈ ખલનાયકનો નહીં. જો મને લાગે કે કોઈ વ્યક્તિ મૂળભૂત રીતે અપ્રામાણિક કે નકલી છે, તો હું તેનો ફોટો ન પાડી શકું. જ્યારે કોઈ ચહેરો મુખવટો પહેરેલો હોય, ત્યારે તે કૃત્રિમતા મને દેખાઈ આવે છે અને હું ફોટોગ્રાફી દ્વારા તે મુખવટો હટાવી શકતો નથી. તે મને પરેશાન કરે છે. એટલે હું આવા લોકોના ફોટા પાડવાનું ટાળું છું. અલબત્ત, આ મારો અંગત દ્રષ્ટિકોણ છે. જેને હું નકલી માનું છું તે કદાચ બીજાની નજરમાં સાચો પણ હોઈ શકે.`,
    
    "pullquote-2": `"દરેક ચહેરો એક વાર્તા વહન કરે છે, પોતાની આગવી સહી ધરાવે છે. તે વાર્તા શોધવી એ એક આનંદ છે."`,
    
    "theme-3": `III. મિલન અને સાક્ષાત્કાર <span>મોરારી બાપુ અને અમરનાથ પર જોખમ</span>`,
    "q6": `Q: તમે પુષ્કળ પોટ્રેટ પુસ્તકો બનાવ્યા છે. કઈ હસ્તીઓ સાથે કામ કરવાનો અનુભવ સૌથી રસપ્રદ રહ્યો? કોઈ વિશેષ સ્મરણો જે યાદ રહી ગયા હોય?`,
    "a6": `A: હું ભાગ્યશાળી રહ્યો છું કે મને જુદા જુદા ક્ષેત્રની ઘણી બધી વ્યક્તિઓ સાથે સમય ગાળવાની તક મળી છે, અને તે પણ માત્ર બે-ચાર કલાક માટે નહીં પરંતુ સતત બે-ત્રણ દિવસ સુધી. બધામાંથી કોઈ એક અનુભવને શ્રેષ્ઠ ગણાવવો ઘણો મુશ્કેલ છે. છતાં પણ એક સંસ્મરણ જે મનમાં હજુ પણ તાજું છે, તે પૂજ્ય મોરારી બાપુ પરના એક ફોટો પુસ્તકના કામ સમયનું છે.
    <br><br>
    હું તેમનો ફોટો લેવા માટે જગન્નાથ પુરી ગયો હતો. ત્યાંનું વાતાવરણ આખું અલગ હતું, સંસ્કૃતિ અલગ હતી અને મને કોઈ ઓળખતું નહોતું. બાપુની આજુબાજુ એટલા બધા લોકો હતા કે હું તેમની નજીક જઈ શકતો નહોતો. મેં ધાર્યું કે તેઓ મને ઓળખીને બોલાવશે, પણ તેમના સુધી પહોંચવા માટે ઘણી બધી અડચણો પાર કરવી પડતી હતી. તેથી મેં બે દિવસ રાહ જોઈ. ત્રીજા દિવસે, હું બધી મર્યાદાઓ ઓળંગીને છેક અંદર પહોંચી ગયો.
    <br><br>
    જ્યારે તેમણે મને જોયો, ત્યારે તેમણે મને પાસે બોલાવ્યો અને પૂછ્યું, “બેટા, તું અહીં સુધી કેવી રીતે પહોંચ્યો?” મેં તેમને કહ્યું, “બાપુ, હું તમારો ફોટો પાડવા આવ્યો છું. હું એક ફોટો બુક બનાવી રહ્યો છું અને હું સવારથી સાંજ સુધી તમારી સાથે રહેવા માંગું છું.” તે ક્ષણે તેઓ પચાસ કે સાઠ લોકોથી ઘેરાયેલા હતા, અને તે બધાએ મને બાપુના પગ ન સ્પર્શવા અને આટલી સહજતાથી વાત કરવા બદલ ટોક્યો. પણ હું તેમને બાળપણથી જાણતો હતો. મને એવું નહોતું કે ઔપचारિક વ્યવહાર જરૂરી છે. તેઓ મારાથી વડીલ છે, અને હું વડીલોનો આદર કરું જ છું. તે આપણી સંસ્કૃતિ છે. પણ કોઈ આધ્યાત્મિક ગુરુ હોવાને કારણે મારે સાષ્ટાંગ દંડવત પ્રણામ કરવા જ પડે એવું હું નથી માનતો. હું ખોટો હોઈ શકું, પણ મેં જે આધ્યાત્મિક ગુરુઓના ફોટા પાડ્યા છે તેમાંથી કોઈએ ક્યારેય વાંધો નથી લીધો. મોરારી બાપુ હોય, રમેશભાઈ ઓઝા હોય કે શ્રી શ્રી રવિશંકર હોય, કોઈએ ક્યારેય મને પૂછ્યું નથી કે તું શા માટે પગે ન લાગ્યો.
    <br><br>
    બીજા દિવસે જ્યારે મને ફરીથી ચાર વાગ્યે બોલાવવામાં આવ્યો, ત્યારે થોડો ઝરમર વરસાદ પડી રહ્યો હતો. હું બાપુના રૂમ તરફ ગયો ત્યારે આખો રસ્તો અને દાદર લોકોથી ખીચોખીચ ભરેલો હતો. ત્યાં લોકો મારી ટીકા કરી રહ્યા હતા કે મારા જેવા વ્યક્તિએ કોઈ સંતને હેરાન ન કરવા જોઈએ કે તેમની સાધનામાં ખલેલ ન પહોંચાડવી જોઈએ. એક ક્ષણ માટે મને પણ લાગ્યું કે હું કંઈક ખોટું કરી રહ્યો છું. પણ જે ક્ષણે હું તેમને મળ્યો, તે શંકા ગાયબ થઈ ગઈ. તેમણે મને સાદગીથી કહ્યું, “હું મારું કામ કરું છું, તું તારું કર.” પછી તેમણે પોતાની દિનચર્યા શરૂ રાખી - સૂર્યને અર્ઘ્ય આપવું, તુલસીના છોડને પાણી પાવું - અને મને તે બધું જ કેપ્ચર કરવાની પરવાનગી આપી. પચ્ચીસ મિનિટમાં મેં લગભગ દોઢસો ફોટા પાડ્યા. તેમણે સહેજ પણ ખચકાટ ન દાખવ્યો.`,
    
    "q7": `Q: તમારે મુશ્કેલ પરિસ્થિતિઓનો પણ સામનો કરવો પડ્યો હશે.`,
    "a7": `A: હા, ચોક્કસ. મને બરાબર વર્ષ યાદ નથી, પણ મને લાગે છે કે ૧૯૯૮ની સાલ હતી જ્યારે અમરનાથમાં ભૂસ્ખલન થયું હતું અને ચાર કે પાંચ હજાર લોકોના મોત થયા હતા. હું તે સમયે મુંબઈમાં હતો અને મને ત્યાં જઈને ફોટોગ્રાફ્સ લેવાની જવાબદારી સોંપવામાં આવી હતી. મુખ્ય તંત્રી હરિકિશન મહેતાએ મને બોલાવ્યો - જેમની હું ખૂબ ઈજ્જત કરું છું - અને તેમણે મને કહ્યું કે તારે જવું પડશે કારણ કે બાકીના બધા ના પાડી રહ્યા છે. તેમને લાગ્યું કે આ ખૂબ મુશ્કેલ છે. તેમણે પૂછ્યું કે શું હું જઈશ? હું યુવાન હતો, એટલે મને ઘણો ઉત્સાહ હતો. જો બીજા બધા ના પાડતા હોય તો મને એ કામ કરવામાં વધુ રસ પડતો. એટલે હું ગયો.
    <br><br>
    મુંબઈથી હું અમદાવાદ ગયો, પછી દિલ્હી અને ત્યાંથી શ્રીનગર. શ્રીનગરથી આર્મી અમને હેલિકોપ્ટર દ્વારા શેષનાગ લઈ ગઈ. ત્યાં કેટલાક વિદેશી પત્રકારો પણ હતા, પણ હું ભારતીય હોવાથી મને હેલિકોપ્ટરમાં મુસાફરી કરવાની પ્રથમ તક મળી. હું ઘણો રાજી થયો કે આવી મહત્વની ઘટનાને કવર કરવાની કેવી અદભુત તક મળી છે. પણ જ્યારે હું ત્યાં ઉતર્યો અને મારી આસપાસનું દ્રશ્ય જોયું તો તે હૃદયદ્રાવક હતું. ફોટા પાડતી વખતે હું ધ્રૂજી રહ્યો હતો - ઠંડીના કારણે નહીં, પરંતુ જે ભયાનક દ્રશ્ય હું જોઈ રહ્યો હતો તેનાથી.
    <br><br>
    પાછા ફરતી વખતે હેલિકોપ્ટરમાં પાયલોટ, વધુ એક વ્યક્તિ અને હું હતા. પછી તેમણે તેમાં મૃતદેહો લોડ કર્યા. લગભગ વીસ જેટલા મૃતદેહો એકબીજા પર ખડકેલા હતા. હેલિકોપ્ટર ટેક-ઓફ થયું ત્યારે મારે તે મૃતદેહોની વચ્ચે ઊભા રહેવું પડ્યું અને બારીમાંથી હવાઈ દ્રશ્યોના ફોટા પાડવા પડ્યા. અત્યારે પણ જ્યારે હું એ ક્ષણો યાદ કરું છું ત્યારે મારી અંદર એક ધ્રુજારી ઊભી થાય છે. તમારી આસપાસ વીસ મૃતદેહો હોય, કોઈનો હાથ તમારા પગને સ્પર્શી રહ્યો હોય અને છતાં પણ અલિપ્ત રહીને એક તટસ્થ નિરીક્ષક તરીકે તે દ્રશ્યને કેમેરામાં કેદ કરવું - તે સરળ નથી. તમે એ વિચારી ન શકો કે આ કોનું સગું છે, અથવા તેમના પરિવારને આ મૃતદેહ મળશે કે નહીં. તમે માત્ર તમારું કામ જ કરી શકો. એ ત્રણ-ચાર દિવસ ક્યારેય ભૂલી શકાય તેમ નથી.`,
    
    "pullquote-3": `"તમારી આસપાસ વીસ મૃતદેહો હોય અને છતાં પણ અલિપ્ત રહીને એક તટસ્થ નિરીક્ષક તરીકે તે દ્રશ્યને કેમેરામાં કેદ કરવું - તે સરળ નથી."`,
    
    "theme-4": `IV. પ્રકાશનું તત્વજ્ઞાન <span>અહંકાર, વિજ્ઞાન અને ડિજિટલ યુગ</span>`,
    "q8": `Q: ફોટોગ્રાફી એ કલા અને વિજ્ઞાન બંને છે. તમે તેને કેવી રીતે જુઓ છો?`,
    "a8": `A: હું એક સરેરાશ વિદ્યાર્થી હતો, અને વિજ્ઞાન ક્યારેય મારા મગજમાં બેઠું નથી. તેથી મારી પાસે ફોટોગ્રાફીને એક કલા તરીકે જોવા સિવાય કોઈ વિકલ્પ નથી. અને તે એક અદ્ભુત કલા છે. તેના દ્વારા મેં ઘણું મેળવ્યું છે - સામાજિક રીતે, આર્થિક રીતે અને કદાચ સૌથી મહત્વપૂર્ણ રીતે, વ્યક્તિગત વિકાસના સંદર્ભમાં. ફોટોગ્રાફી એ મને કમળની જેમ અલિપ્ત રહીને કામ કરવાનું શીખવ્યું છે. તેણે મને શીખવ્યું છે કે હું જે છું તે જ રહું.
    <br><br>
    અગાઉ જ્યારે હું સુંદર સૂર્યોદય, સૂર્યાસ્ત કે કુદરતી દ્રશ્યનો ફોટો પાડીને પાછો ફરતો ત્યારે મને એક ગર્વ થતો કે મેં કંઈક અસાધારણ સર્જન કર્યું છે, મારી પાસે અદભુત કલાત્મક ક્ષમતા છે. પણ પાછળથી મને સમજાયું કે કોઈ પણ સુંદર સૂર્યોદય કે સૂર્યાસ્તનો ફોટો પાડી શકે છે. તેમાં કોઈ બહુ મોટી સિદ્ધિ નથી. મારું નસીબ એ છે કે મને ત્યાં હાજર રહેવાની તક મળી છે. હું આસામ ગયો છું, હિમાલય ગયો છું, એવી જગ્યાઓ જ્યાં ઘણા લોકો નથી પહોંચી શકતા.
    <br><br>
    Apply to: હું જે ફોટા પાછા લાવું છું તે માત્ર એક માધ્યમ છે. એ રીતે હું માત્ર એક ટપાલી છું અને ટપાલીને પત્ર વહન કરવાનો કોઈ અહંકાર ન હોય. ફોટોગ્રાફર તરીકે હું માત્ર એક માધ્યમ છું. સૂર્યોદય અને સૂર્યાસ્ત પોતાની રીતે જ ભવ્ય છે. તે અનુભૂતિએ મારામાં રહેલા દર્શકને વધુ મજબૂત બનાવ્યો. એક સમયે મારામાં જે પણ અહંकार આવ્યો હશે તે ધીમે ધીમે અદૃશ્ય થઈ ગયો. આજે પણ જ્યારે મારા વિદ્યાર્થીઓ - સોળ કે સત્તર વર્ષના છોકરા-છોકરીઓ - તેમના ફોટા મારી પાસે લાવે છે, ત્યારે મને તે જ જિજ્ઞાસા અને અહોભાવનો અનુભવ થાય છે જે તેઓ અનુભવે છે. તે અજાયબીનો ભાવ મને ક્યારેય છોડીને ગયો નથી.`,
    
    "q9": `Q: શું ટેક્નોલોજીએ ફોટોગ્રાફીને એટલી સરળ બનાવી દીધી છે કે હવે કોઈ પણ સારો ફોટો પાડી શકે છે?`,
    "a9": `A: હા, અને તે સાચું છે. આજના ડિજિટલ યુગમાં ખરાબ ફોટો પાડવા માટે પણ ઘણી મહેનત કરવી પડે છે. કેમેરા એટલા તો આધુનિક છે કે ફોટા આપોઆપ જ સારા આવે છે. ટેક્નોલોજીએ આખા માધ્યમને બદલી નાખ્યું. પહેલાં ફિલ્મ હતી, જેની સાથે જુદી જુદી સ્પીડ, લોડિંગ, શૂટિંગ, ડેવલપિંગ અને છેલ્લે પ્રિન્ટ થયેલા ફોટાને હાથમાં પકડવાનો રોમાંચ સંકળાયેલો હતો. ડિજิตલ ટેક્નોલોજી આવતાની સાથે જ એ બધું અદૃશ્ય થઈ ગયું.
    <br><br>
    પહેલો બદલાવ એ આવ્યો કે ફોટોગ્રાફી સસ્તી થઈ ગઈ. ૧૯૯૯ કે ૧૯૯૦ માં જો તમે ૩૬ ફ્રેમનો રોલ શૂટ કરો, તો પ્રિન્ટ પાછી આવે ત્યાં સુધીમાં સાતસો-આઠસો રૂપિયા ખર્ચાઈ જતા. ફોટોગ્રાફીના વિદ્યાર્થી માટે તે બહુ મોટી રકમ હતી. આજે તમે તમારા ફોટા તરત જ કોમ્પ્યુટર પર જોઈ શકો છો, તેથી પ્રક્રિયા સરળ અને સસ્તી બંને બની છે. નવા લેન્સે પણ કામ ઘણું સરળ બનાવ્યું છે. પછી ઇન્ટરનેટ આવ્યું અને ફોટા મોકલવા સરળ થઈ ગયા. હું તમને સેકન્ડોમાં ફોટો મોકલી શકું છું.
    <br><br>
    એટલે ફોટોગ્રાફરો માટે ફોટોગ્રાફી સરળ બની ગઈ છે, પણ સાથે જ તમારી ગુણવत्ता સાબિત કરવી ઘણી અઘરી બની ગઈ છે કારણ કે સ્પર્ધા અતિશय વધી ગઈ છે. આજે લગભગ કોઈ પણ સારો ફોટો પાડી શકે છે. ઘણા લોકો ફેસબુક, ઇન્સ્ટાગ્રામ અને બીજા ઘણા પ્લેટફોર્મ પર આકર્ષક ચિત્રો પોસ્ટ કરે છે. "સારા ફોટોગ્રાફર" નો એકાધિકાર હવે રહ્યો નથી. તમારે રોજ પોતાને સાબિત કરવા પડે છે.`,
    
    "q10": `Q: શું વિજ્ઞાનની પ્રગતિને કારણે કલાનું ધીમું મૃત્યુ થયું છે?`,
    "a10": `A: ના, હું તેની સાથે બિલકુલ સંમત નથી. છેવટે તો ગુજરાતીમાં કહેવત છે ને: “કૂવામાં હોય તો જ હવાડામાં આવે.” બીજા શબ્દોમાં કહીએ તો, જો મૂળ ફોટોગ્રાફ શક્તિાળી હોય, તો જ એડિટિંગ તેને મદદરૂપ થઈ શકે છે. જો મૂળ ઈમેજ જ નબળી હોય, તો એડિટિંગ પણ તેને બચાવી શકતું નથી. ફોટોશોપ અને અન્ય એડિટિંગ ટૂલ્સ માત્ર વધારાની એક્સેસરીઝ છે - જેમ કે ઘરેણાં, જેમ કે મેકઅપ.
    <br><br>
    દુલ્હન ગમે તેટલી સુંદર સજ્જ હોય, ભારે મેકઅપ અને ઘરેણાં પહેર્યા હોય, પણ તેનું કુદરતી સૌંદર્ય જ સૌથી મહત્વનું છે. જો તે મૂળભૂત રીતે સુંદર હશે, તો તે મેકઅप વગર પણ સુંદર જ લાગશે. મેકઅપ વગરનો ચહેરો પણ એક સુંદર ચહેરો હોઈ શકે છે.`,
    
    "pullquote-4": `"ટપાલીને પત્ર વહન કરવાનો કોઈ અહંકાર ન હોય. ફોટોગ્રાફર તરીકે હું માત્ર એક માધ્યમ છું."`,
    
    "theme-5": `V. જ્ઞાનની મશાલ સોંપવી <span>શિક્ષણ, સંગીત અને સર્જનાત્મક પ્રવૃત્તિઓ</span>`,
    "q11": `Q: તમે ફોટોગ્રાફી શીખવવા અને વર્કશોપ યોજવા સાથે સંકળાયેલા છો. આ કલા વાસ્તવમાં ક્યાં સુધી શીખવી શકાય?`,
    "a11": `A: હવે ઘણું સારું છે. અમારા સમયમાં ફોટોગ્રાફી શીખવતી કોઈ સંસ્થાઓ નહોતી. આજે ઘણી કોલેજો અને સંસ્થાઓ શીખવે છે. અને નવા સાધનોને કારણે શીખવવાનું પણ સરળ બન્યું છે. પરંતુ મને હંમેશા લાગ્યું છે કે ફોટોગ્રાફી ક્યારેય બંધ રૂમમાં કે વર્ગખંડમાં જ ન શીખી શકાય. હું કોલેજોમાં શીખવું છું, પણ પહેલા ત્રણ-ચાર પ્રારંભિક વર્ગો પછી હું સામાન્ય રીતે વિદ્યાર્થીઓને બહાર લઈ જાઉં છું. અમે પોંડિચેરી, આસામ અને હિમાલય જેવી જગ્યાએ જઈએ છીએ અને ત્યાં વર્કશોપ યોજીએ છીએ.
    <br><br>
    મારી અંગત માનયતા છે કે વિદ્યાર્થીઓને ઘણી ભૂલો કરવાની છૂટ આપવી જોઈએ. હું તેમને કહું છું કે પુષ્કળ ભૂલો કરો અને તેમાંથી શીખો. કુદરતી દ્રશ્યોની ફોટોગ્રાફી એ એક એવું ક્ષેત્ર છે જ્યાં ભૂલો તરત જ દેખાઈ આવે છે. ભૂલ દ્રશ્યમાં નથી હોતી, પણ તમે તેને કેવી રીતે કેપ્ચર કરો છો તેમાં હોય છે. જો તમે તે બરાબર ન કરો તો ભૂલ સ્પષ્ટ દેખાય. આ રીતે જ માણસ શીખે છે - પોતાની ભૂલોને સ્પષ્ટપણે જોઈને. હું માનું છું કે દરેક વ્યક્તિની અંદર એક ફોટોગ્રાફર છુપાયેલો હોય છે. અસલી પ્રશ્ન એ છે કે તમે તે આંતરિક ફોટોગ્રાફરને કેટલી તક આપો છો.`,
    
    "q12": `Q: સંજય, ફોટોગ્રાફી સિવાય તમારા અન્ય શોખ કયા કયા છે?`,
    "a12": `A: મને વાંચન ખૂબ ગમે છે. મારા માટે વાંચન શ્વાસ લેવા જેટલું જ મહત્વનું છે. મારે વાંચવું જ પડે. મને સારું સંગીત પણ ઘણું ગમે છે. વાંચન અને સંગીત વિના મારું જીવન શક્ય નથી. મને બંનેનો અતિશય શોખ છે અને કદાચ એટલે જ હું કોઈ મોટો લેખક કે સંગીતકાર ન બની શક્યો - કારણ કે હું પુસ્તકો અને સંગીતનો પૂર્ણ-સમયનો ચાહક છું. હું બધું જ વાંચું છું: વાર્તાઓ, ગદ્ય, નિબંધો, પત્રો, કવિતાઓ - બધું જ. અને બધી ભાષાઓમાં વાંચું છું.
    <br><br>
    સંગીતમાં મને ભારતીય શાસ્ત્રીય સંગીત વધુ ગમે છે, જો કે મને કોઈ રોક બેન્ડ સામે વાંધો નથી. હું રોક મ્યુઝિકનો પણ આનંદ લઉં છું, જેટલું મને સમજાય. મારો પુત્ર રોક અને જાઝ બેન્ડમાં છે અને જ્યારે તે મને વસ્તુઓ સમજાવે છે, શીખવે છે અને બતાવે છે ત્યારે મને ખૂબ ગમે છે. હું સંગીતના દરેક સ્વરૂપની પ્રશંસા કરું છું, પણ શાસ્ત્રીય સંગીત મને થોડું વધુ સ્પર્શે છે કારણ કે હું તેને વધુ સારી રીતે સમજી શકું છું.`,
    
    "q13": `Q: તમે આપણા ઘણા મોટા સંગીતકારોના ફોટા પાડ્યા છે. તે અનુભવ કેવો હતો?`,
    "a13": `A: હા, મેં લગભગ તમામ અગ્રણી ભારતીય શાસ્ત્રીય સંગીતકારોના ફોટા પાડ્યા છે. પણ સાચું કહું તો, મારા મનમાં હંમેશાં એક અધૂરપ રહેતી કારણ કે હું સંગીત જાણતો નહોતો. મેં કલાકારોની ઉત્કૃષ્ટ ક્ષણોને કેમેરામાં કેદ કરીને - તેમના શ્રેષ્ઠ ફોટાઓ દ્વારા તે કમી પૂરી કરવાનો પ્રયત્ન કર્યો.
    <br><br>
    એક રીતે, હું મારું કામ શક્ય તેટલું કાળજીપૂર્વક અને સુંદર રીતે કરીને તે ખોટ પૂરી કરવા માંગતો હતો. હું સંગીત જાણતો નથી એટલે મને થાય કે મારે એવું કંઈક કરવું જોઈએ કે સંગીતકાર મને યાદ રાખે. તેથી જ્યારે પંડિત શિવકુમાર શર્મા કે ઉસ્તાદ ઝાકિર હુસૈન મને ફોન કરીને કહે કે, “ફોટો ખૂબ જ સુંદર આવ્યો છે - કૃપા કરીને અમને આપો,” ત્યારે મને એવું લાગે છે કે જાણે હું કોઈ સુંદર રાગ શીખી ગયો છું.`,
    
    "q14": `Q: સંજય, જો તમે આજે પ્રખ્યાત ફોટોગ્રાફર ન હોત, તો તમને શું લાગે છે કે તમે શું બન્યા હોત?`,
    "a14": `A: મને લાગે છે કે હું શિક્ષક બન્યો હોત. મને અત્યારે એવું લાગે છે કારણ કે છેલ્લા ઘણા વર્ષોથી હું શિક્ષણ આપવાનું કામ પણ કરી રહ્યો છું. એક શિક્ષક બનવું, માર્ગદર્શક બનવું - ખાસ કરીને હવે જ્યારે હું 60 વર્ષનો થવા આવ્યો છું - એટલો સંતોષ આપે છે કે જો હું ફોટોગ્રાફી ન કરતો હોત તો ચોક્કસપણે શિક્ષક બન્યો હોત.
    <br><br>
    મને વિદ્યાર્થીઓ સાથે રહેવું અને તેમની તાજગી, તેમની ઉર્જા ખૂબ ગમે છે. અમારા એક વરિષ્ઠ ફેકલ્ટી સભ્ય ક્રિસ્ટોફર બેનિંગર - એક અમેરિકન આર્કિટેક્ટ જે ઘણા વર્ષો ભારતમાં રહ્યા - તેમણે એકવાર આપણને બહુ સુંદર વાત શીખવી હતી: “તમારા વિદ્યાર્થીને તમે આપી શકો તેવી સૌથી મોટી ભેટ એ છે કે તેને હંમેશા વિદ્યાર્થી રહેતા શીખવવું.” એ વાક્ય મારા દિલમાં વસી ગયું છે. તે ખૂબ પ્રેરણાદાયક લાગે છે. જ્યારે હું ભણાવવા જાઉં છું ત્યારે બે-ત્રણ કલાક પછી થાકીને નથી પાછો ફરતો. હું પોતે કંઈક નવું શીખીને, નવી ઉર્જા સાથે પાછો આવું છું. અને તે જ મને આગળ ધપાવે છે.`,
    
    "pullquote-5": `"તમારા વિદ્યાર્થીને તમે આપી શકો તેવી સૌથી મોટી ભેટ એ છે કે તેને હંમેશા વિદ્યાર્થી રહેતા શીખવવું."`,
  },
  mr: {
    "sidebar-quote": `"प्रत्येक पोर्ट्रेटच्या मागे एक न लिहिलेले आत्मचरित्र असते. मी त्यांचे चेहरे टिपत नाही; मी त्यांचे साहित्य टिपतो."`,
    "intro-1": `त्यांचे नाव गुजरात आणि संपूर्ण भारतातील कला प्रदर्शनांमध्ये आणि अनेक छायाचित्र-पुस्तके व कॉफी-टेबल पुस्तकांच्या मुखपृष्ठांवर दिसते. तरीही सार्वजनिक भाषा अनेकदा या प्रतिमांमागील व्यक्तिमत्त्वाचे वर्णन करण्यास अपुरी पडते - एक असा छायाचित्रकार जो आपल्या लेन्सद्वारे दृश्ये आणि चेहऱ्यांना बोलते करतो, या कलेचा एक शांत उस्ताद, कॅमेरा हातात असलेला एक कवी: <strong>संजय वैद्य</strong>.`,
    "intro-2": `२००७ पासून, त्यांची विशिष्ट छायाचित्र-पुस्तके नियमितपणे प्रकाशित होत आहेत, विशेषत: नामवंत व्यक्तींवरील त्यांची पोर्ट्रेट मालिका. ही पुस्तके अनेकदा छायाचित्रांच्या संग्रहापेक्षा अधिक त्या व्यक्तींची जिव्हाळ्याची दृश्य संस्मरणे असल्यासारखी वाटतात. त्यांनी त्यांना व्यापक मान्यता आणि भारतातील आघाडीच्या छायाचित्रकारांमध्ये स्थान मिळवून दिले आहे.
    <br><br>
    त्यांनी छायाचित्रित केलेल्या असंख्य दिग्गज व्यक्तींमध्ये गुजराती साहित्यातील सुरेश दलाल, तारक मेहता, चंद्रकांत बक्षी आणि गुणवंत शाह यांसारखे साहित्यिक; भारतीय शास्त्रीय संगीतातील दिग्गज पंडित भीमसेन जोशी, पंडित जसराज, पंडित शिवकुमार शर्मा, उस्ताद अमजद अली खान, बेगम परवीन सुलताना, पंडित हरिप्रसाद चौरसिया, पंडित राजन-साजन मिश्रा, उस्ताद झाकीर हुसेन आणि ग्रॅमी विजेते पंडित विश्व मोहन भट्ट; आध्यात्मिक नेते जसे की मोरारी बापू, श्री श्री रविशंकर, प्रमुख स्वामी महाराज आणि रमेशभाऊ ओझा; आणि चित्रपटसृष्टीतील दिग्गज व्यक्ती जसे की गुलजार, अमिताभ बच्चन, ऐश्वर्या राय बच्चन, आशा भोसले, मनोज बाजपेयी, तबू आणि इरफान खान यांचा समावेश आहे.`,
    "intro-3": `अहमदाबादमध्ये स्थायिक असलेले संजय छायाचित्रण शिकवतात, कार्यशाळा आयोजित करतात आणि सर्जनशील दृश्य कथाकथनाचा शोध घेतात. त्यांचे भाषा आणि साहित्यावरील अतूट प्रेम त्यांना साहित्यिक प्रकाशन, संस्कृत लोक-संगीत फ्युजन आणि प्रसिद्ध गुजराती लेखकांवर समृद्ध माहितीपट तयार करण्याकडे आकर्षित करते. जेव्हा त्यांना मुलाखतीसाठी विचारण्यात आले, तेव्हा त्यांनी आपल्या नेहमीच्या नम्रतेने उत्तर दिले: <em>“मी बोलण्यात फारसा चांगली नाही,”</em> आणि मग हा संवाद सुरू झाला.`,
    
    "theme-1": `I. एका ध्येयाचा उगम <span>सुरुवात आणि व्यवसाय</span>`,
    "q1": `Q: संजय, छायाचित्रणामध्ये ही असामान्य आवड कुठून आली आणि तिचा विकास कसा झाला?`,
    "a1": `A: छायाचित्रण ही माझी नेहमीच आवड, माझा छंद राहिला आहे. मी कधीच विचार केला नव्हता की मी याला व्यावसायिकरित्या स्वीकारेन. मला नेहमीच निसर्गाची आवड राहिली आहे आणि माझ्या आजूबाजूला घडणाऱ्या प्रत्येक गोष्टीत रस होता. तरुण असतानाही, मला असे वाटायचे की जरी मी घटना घडताना पाहत होतो, तरी मी पूर्णपणे त्यांच्या आत नव्हतो. कुठेतरी, मला त्यात सामील व्हायचे होते. मला वाटते की माझ्यात नेहमीच काहीतरी होते ज्याला एखादा क्षण पाहायचा होता आणि तो गोठवून ठेवावा लागला. ज्या क्षणी मी पहिल्यांदा कॅमेरा हातात धरला आणि पहिली काही छायाचित्रे काढली, मला माहित होते की हेच मला करायचे आहे. मी आसामला गेलो असो की इतर कोठेही, मला एखादी गोष्ट पाहण्याची, तिचे छायाचित्र काढण्याची आणि ती परत आणण्याची प्रक्रिया खूप आवडायची. त्या संपूर्ण अनुभवाने मला अफाट आनंद दिला. अशा प्रकारे मी या क्षेत्रात प्रवेश केला.`,
    
    "q2": `Q: छंद म्हणून छायाचित्रण ठीक आहे, पण व्यवसाय म्हणून ते स्वीकारणे धोक्याचे नव्हते का? एका नवीन छायाचित्रकारासाठी त्याचे अर्थशास्त्र कसे काम करते?`,
    "a2": `A: हे नक्कीच धोक्याचे वाटले. माझ्या कुटुंबात, माझी आजी नेहमी म्हणायची, “कधीपर्यंत तू हे फोटो काढत राहणार? जर लग्नाचा प्रस्ताव घेऊन कोणी आले आणि मुलाचे काय काम आहे असे विचारले, तर आम्ही काय सांगणार - की तो फोटो काढतो?” त्या दिवसांत छायाचित्रणाला अनेकदा दुय्यम दर्जाचे काम मानले जात असे. मी कधीच हुशार विद्यार्थी नव्हतो आणि माझा शैक्षणिक रेकॉर्ड खूपच सामान्य होता. त्यामुळे माझी कधीच डॉक्टर किंवा इंजिनियर बनण्याची महत्त्वाकांक्षा नव्हती. मी आधी छंद म्हणून छायाचित्रण सुरू केले आणि नंतर, नकळत ते कधी माझा व्यवसाय बनले हे मला समजलेच नाही.
    <br><br>
    त्या दिवसांत छायाचित्रणाचे अर्थशास्त्र खूप वेगळे होते. चित्रकलेच्या तुलनेत, छायाचित्रणाला एक खालची कला मानली जात असे - खरं तर, अनेक लोक याला कला देखील मानत नव्हते. सौंदर्यशास्त्रापेक्षा तांत्रिक गोष्ट म्हणून याकडे पाहिले जात असे. नंतर, डिजिटल तंत्रज्ञानाच्या आगमनाने हे माध्यम पूर्णपणे बदलले. त्याआधीही, film छायाचित्रण आणि नंतर टेलिव्हिजन आणि सिनेमाच्या माध्यमातून, विशेषत: १९९० च्या दशकानंतर, छायाचित्रणाला मोठी ओळख मिळाली. त्याचे आर्थिक मूल्यही बदलले. आज, छायाचित्रकार किती पैसे कमावू शकतात याची कोणी कल्पनाही करू शकत नाही. भारतात, अनेक छायाचित्रकार आता चित्रपट किंवा दूरदर्शन मालिकांमधील कॅमेरामनपेक्षा जास्त कमावतात.`,
    
    "pullquote-1": `"प्रत्येक छायाचित्र सेकंदाच्या आठव्या भागात जन्माला येते."`,
    
    "theme-2": `II. क्षणाचा खेळ <span>क्षण, चित्रकला आणि प्रकाश</span>`,
    "q3": `Q: तुम्ही चित्रकारही आहात. छायाचित्रकाराने बनवलेली प्रतिमा आणि चित्रकाराने बनवलेली प्रतिमा यात काय फरक आहे?`,
    "a3": `A: मी छायाचित्रकार आहे म्हणून छायाचित्रण श्रेष्ठ आहे असे मी म्हणणार नाही. पण प्रामाणिकपणे सांगायचे तर, मला नेहमीच असे वाटले आहे की जेव्हा तुम्ही पेंटिंग करता, तेव्हा तुम्हाला कामात बदल करण्याचे स्वातंत्र्य असते. जर काही चूक झाली, तर तुम्ही त्याचा आकार, रूप किंवा रंग बदलू शकता. ते स्वातंत्र्य चित्रकलेत असते. छायाचित्रणात असे कोणतेही स्वातंत्र्य नसते. तुम्हाला एकाच क्षणाला पकडावे लागते आणि ते राखून ठेवावे लागते. जर तुम्ही तो क्षण गमावला, तर तो गेला. त्यामुळे तुम्हाला सतर्क राहावे लागेल, क्षण येण्यापूर्वी तो ओळखावा लागेल आणि मग योग्य क्षणी क्लिक करावे लागेल. सलमान रश्दी यांनी एकदा एक सुंदर वाक्य म्हटले होते: “प्रत्येक छायाचित्र सेकंदाच्या आठव्या भागात जन्माला येते.” मी याकडे याच दृष्टीने पाहतो. वेळेच्या त्या छोट्याशा भागात, तुम्हाला सिद्ध करावे लागेल की तुमचे छायाचित्र किती शक्तिशाली असू शकते.`,
    
    "q4": `Q: तुम्ही निसर्ग छायाचित्रणाने सुरुवात केली होती, पण आज तुम्ही पोर्ट्रेट छायाचित्रकार म्हणून ओळखले जाता. हा प्रवास कसा झाला?`,
    "a4": `A: सुरुवातीला फारसे पर्याय नव्हते. वन्यजीव, निसर्ग, कॅन्डीड किंवा पोर्ट्रेट फोटोग्राफी यात आज आपण विचार करतो तसा मोठा फरक नव्हता. आणि गुजरात किंवा अहमदाबादमध्येही छायाचित्रण शिकवणारी कोणतीही संस्था नव्हती. मी स्वतः चुका करून शिकलो. आधी कॅमेरा खरेदी करावा लागला, मग फिल्म रोल, मग फोटो काढायचे, आणि नंतर ते कोणा अनुभवी व्यक्तीला दाखवायचे - आणि जर ती व्यक्ती चांगल्या मूडमध्ये असेल, तर कदाचित ते तुम्हाला एक-दोन गोष्टी शिकवतील. मुख्य नियम सोपा होता: तुम्ही आधी केलेली चूक पुन्हा कधीही करू नका.
    <br><br>
    निसर्गचित्रे अधिक सहजतेने कॅप्चर करता येत असत कारण त्यात विविधता होती - वेगवेगळी झाडे, वेगवेगळी तळी, वेगवेगळी दृश्ये. चेहऱ्यांकडे माझा कल नकळत झाला. मला वाटत नाही की मी जाणीवपूर्वक पोर्ट्रेटकडे वळण्याचा निर्णय घेतला होता. पण जसजसा मी पुढे गेलो, तसतसे मला जाणवले की मानवी चेहरे देखील निसर्गचित्रांसारखीच विविधता देतात. मी ४० वर्षांपासून छायाचित्रण करत आहे, आणि मला अजूनही दोन चेहरे सारखे दिसलेले नाहीत. अगदी जुळी मुले देखील मला सारखी वाटत नाहीत. इतक्या चेहऱ्यांमधून जाणे हा एक असाधारण अनुभव आहे.
    <br><br>
    प्रत्येक चेहऱ्यावर एक कथा असते, त्याची स्वतःची एक लपलेली स्वाक्षरी असते. ती कथा शोधणे हा एक आनंद आहे. यात धोका आहे, पण रोमांच आणि आनंदही आहे. जर तुम्ही एखाद्या व्यक्तीच्या चेहऱ्यामागील कथा समोर आणू शकलात, तर तुम्ही यशस्वी झाला आहात. अन्यथा, छायाचित्र कितीही आकर्षक असले तरी ते केवळ वरवरचेच राहते. पोर्ट्रेटमध्ये त्या व्यक्तीचे व्यक्तिमत्त्व दिसून आले पाहिजे. म्हणूनच मी त्या व्यक्तीला आधी भेटणे पसंत करतो. अगदी दुसऱ्या दिवशी मला कोणाचे शूट करायचे असेल, तरी मला आधी त्यांच्यासोबत दोन-तीन तास घालवायला आवडते - फक्त साधी बातचीत, काहीही औपचारिक नाही. त्या वेळेत मी चेहऱ्याचे काळजीपूर्वक निरीक्षण करतो. मी त्या व्यक्तीला, त्यांच्या आवडीनिवडी पाहतो आणि हे समजून घेण्याचा प्रयत्न करतो की चेहऱ्याचा कोणता भाग अधिक प्रामाणिकपणे बोलतो. डोळे मला अत्यंत शब्दबद्ध आणि सत्यवादी वाटले आहेत. आणि आपले काम लेन्सचे असल्याने आपणही प्रामाणिक असले पाहिजे.`,
    
    "q5": `Q: तुम्ही पोर्ट्रेटसाठी ज्या लोकांचे फोटो काढता त्यांची निवड कशी करता?`,
    "a5": `A: आता माझ्याकडे निवड करण्याचे पुरेसे स्वातंत्र्य आहे. पूर्वी मी व्यावसायिक छायाचित्रकार होतो, त्यामुळे जे पैसे द्यायचे त्यांचे फोटो मी काढायचो. आज मी नाही म्हणू शकतो. मी कोणालाही सांगू शकतो की मला त्यांचा फोटो काढायचा नाही, किंवा मला तसे करण्यात सोयीस्कर वाटत नाही. मी एखाद्या अँटीहिरोचा, असामान्य किंवा विक्षिप्त व्यक्तीचा फोटो काढू शकतो, पण खलनायकाचा नाही. जर मला वाटले की एखादी व्यक्ती मुळातच बनावट किंवा कृत्रिम आहे, तर मी त्यांचा फोटो काढू शकत नाही. जेव्हा चेहऱ्यावर मुखवटा असतो, तेव्हा ती कृत्रिमता मला स्पष्टपणे दिसते आणि मी छायाचित्रणाद्वारे तो मुखवटा काढू शकत नाही. ते मला त्रास देते. म्हणून मी अशा लोकांचे फोटो काढणे टाळतो. अर्थात, हा माझा वैयक्तिक दृष्टिकोन आहे. ज्याला मी बनावट मानतो, तो कदाचित दुसऱ्याच्या दृष्टीने तसा नसेल.`,
    
    "pullquote-2": `"प्रत्येक चेहऱ्यावर एक कथा असते, त्याची स्वतःची एक लपलेली स्वाक्षरी. ती कथा शोधणे हा एक आनंद आहे."`,
    
    "theme-3": `III. भेटी आणि प्रकटीकरण <span>मोरारी बापू आणि अमरनाथवरील धोका</span>`,
    "q6": `Q: तुम्ही अनेक पोर्ट्रेट पुस्तके तयार केली आहेत. कोणत्या व्यक्तींसोबत काम करणे सर्वात मनोरंजक राहिले आहे? अशा काही आठवणी ज्या मनात घर करून राहिल्या आहेत?`,
    "a6": `A: मी स्वतःला भाग्यवान समजतो की मला वेगवेगळ्या क्षेत्रातील अनेक लोकांसोबत वेळ घालवण्याची संधी मिळाली, आणि तीही काही तासांसाठी नाही तर सलग दो-तीन दिवस. इतर सर्व अनुभवांमधून एका अनुभवाची निवड करणे खूप कठीण आहे. पण मोरारी बापूंच्या एका फोटो पुस्तकावर काम करत असतानाची एक आठवण अजूनही माझ्या मनात ताजी आहे.
    <br><br>
    मी त्यांचे फोटो घेण्यासाठी जगन्नाथ पुरीला गेलो होतो. तिथले वातावरण पूर्णपणे वेगळे होते, संस्कृती वेगळी होती आणि मला कोणी ओळखत नव्हते. बापूंच्या अवतीभोवती इतके लोक होते की मी त्यांच्याजवळ जाऊ शकत नव्हतो. मी गृहीत धरले की ते मला ओळखून बोलावत असतील, पण त्यांच्यापर्यंत पोहोचण्यासाठी अनेक अडथळे पार करावे लागत होते. म्हणून मी दोन दिवस वाट पाहिली. तिसऱ्या दिवशी, मी शेवटी सर्व अडथळे ओलांडून आत प्रवेश मिळवला.
    <br><br>
    जेव्हा त्यांनी मला पाहिले, त्यांनी मला जवळ बोलावले आणि विचारले, “बेटा, तू इथे कसा पोहोचलास?” मी त्यांना सांगितले, “बापू, मी तुमचे छायाचित्र घेण्यासाठी आलो आहे. मी एक फोटो बुक तयार करत आहे आणि मला सकाळपासून संध्याकाळपर्यंत तुमच्यासोबत राहायचे आहे.” त्या क्षणी ते पन्नास-साठ लोकांनी वेढलेले होते, आणि त्या सर्वांनी मला बापूंचे पाय न पडल्याबद्दल आणि त्यांच्याशी इतक्या सहजपणे बोलल्याबद्दल रागावले. पण मी त्यांना बालपणापासून ओळखत होतो. मला असे वाटले नाही की औपचारिक गोष्टी गरजेच्या होत्या. ते माझ्यापेक्षा मोठे आहेत, नक्कीच, आणि मी मोठ्यांचा आदर करतो. ती आपली संस्कृती आहे. पण कोणी आध्यात्मिक गुरु असल्यामुळे मला अचानक साष्टांग दंडवत घालावाच लागेल असे मला वाटत नाही. मी चुकीचा असू शकतो, पण मी ज्या आध्यात्मिक गुरूंचे फोटो काढले आहेत त्यापैकी कोणीही यावर आक्षेप घेतला नाही. मोरारी बापू असोत, रमेशभाई ओझा असोत किंवा श्री श्री रविशंकर असोत, कोणीही मला कधीही विचारले नाही की तू माझ्या पाया का पडला नाहीस.
    <br><br>
    दुसऱ्या दिवशी जेव्हा मला पुन्हा चार वाजता बोलावण्यात आले, तेव्हा हलकी रिमझिम पाऊस पडत होता. मी बापूंच्या खोलीकडे गेलो तेव्हा संपूर्ण जिना आणि प्रांगण लोकांनी खचाखच भरलेले होते. तिथे लोक माझ्यावर टीका करत होते की माझ्यासारख्या माणसाने एखाद्या संताला त्रास देऊ नये किंवा त्यांच्या साधनेत अडथळा आणू नये. एका क्षणासाठी मलाही वाटले की मी काहीतरी चुकीचे करत आहे का. पण ज्या क्षणी मी त्यांना भेटलो, ती शंका नाहीशी झाली. त्यांनी मला साधेपणाने सांगितले, “मी माझे काम करत आहे, तू तुझे कर।” मग त्यांनी आपली दिनचर्या सुरू ठेवली - सूर्याला जल देणे, तुळशीच्या रोपाला पाणी घालणे - आणि मला सर्व काही सुंदरपणे टिपण्याची परवानगी दिली. पंचवीस मिनिटांत मी सुमारे दीडशे फोटो घेतले. त्यांनी अजिबात आक्षेप घेतला नाही.`,
    
    "q7": `Q: तुम्हाला कठीण परिस्थितींचाही सामना करावा लागला असेल.`,
    "a7": `A: होय, नक्कीच. मला नेमके वर्ष आठवत नाही, पण मला वाटते की १९९८ हे वर्ष होते जेव्हा अमरनाथमध्ये दरड कोसळली होती आणि चार ते पाच हजार लोकांचा मृत्यू झाला होता. मी त्यावेळी मुंबईत होतो आणि मला तिथे जाऊन फोटो घेण्याची जबाबदारी दिली गेली होती. मुख्य संपादक हरिकिशन मेहता यांनी मला बोलावले - अशा व्यक्ती ज्यांचा मी खूप आदर करतो - आणि त्यांनी मला सांगितले की मला जावे लागेल कारण बाकीचे सर्व नकार देत होते. त्यांना वाटत होते की हे खूप कठीण आहे. त्यांनी विचारले की मी जाईन का? मी तरुण होतो, त्यामुळे खूप उत्सुक होतो. जर इतर सर्व नाही म्हणत होते, तर मला ते काम करण्यात अधिक रस वाटला. म्हणून मी गेलो.
    <br><br>
    मुंबईहून मी अहमदाबादला गेलो, मग दिल्ली आणि तिथून श्रीनगर. श्रीनगरहून सैन्याने आम्हाला हेलिकॉप्टरने शेषनागला नेले. तिथे काही परदेशी पत्रकारही होते, पण मी भारतीय असल्याने मला हेलिकॉप्टरने प्रवास करण्याची पहिली संधी मिळाली. मला खूप आनंद झाला की अशा महत्त्वाच्या घटनेला कव्हर करण्याची किती अद्भूत संधी मिळाली आहे. पण जेव्हा मी तिथे उतरलो आणि माझ्या आजूबाजूचे दृश्य पाहिले, तेव्हा ते अत्यंत भयानक होते. फोटो काढताना मी थरथर कापत होतो - थंडीमुळे नाही, तर मी जे भयानक दृश्य पाहत होतो त्या भीतीने.
    <br><br>
    परतीच्या प्रवासात हेलिकॉप्टरमध्ये पायलट, आणखी एक व्यक्ती आणि मी होतो. मग त्यांनी त्यात मृतदेह चढवले. सुमारे वीस मृतदेह एकावर एक रचले होते. हेलिकॉप्टरने उड्डाण केले तेव्हा मला त्या मृतदेहांच्या मध्ये उभे राहावे लागले आणि खिडकीतून हवाई दृश्ये कॅप्चर करावी लागली. आज जेव्हा मी त्या क्षणांची आठवण काढतो, तेव्हा माझ्यात एक थरकाप उडतो. तुमच्या आजूबाजूला वीस मृतदेह असणे, कोणाचा तरी हात तुमच्या पायाला स्पर्श करताना जाणवणे, आणि तरीही अलिप्त राहून एका तटस्थ निरीक्षकाप्रमाणे ते दृश्य कॅमेऱ्यात टिपणे - हे सोपे नाही. हा कोणाचा नातेवाईक आहे, किंवा त्यांच्या कुटुंबाला मृतदेह मिळेल की नाही याचा तुम्ही विचार करू शकत नाही. तुम्ही फक्त तुमचे काम करू शकता. ते तीन-चार दिवस कधीही न विसरता येण्यासारखे आहेत.`,
    
    "pullquote-3": `"तुमच्या आजूबाजूला वीस मृतदेह असणे, आणि तरीही अलिप्त राहून एका तटस्थ निरीक्षकाप्रमाणे ते दृश्य कॅमेऱ्यात टिपणे - हे सोपे नाही."`,
    
    "theme-4": `IV. प्रकाशाचा सिद्धांत <span>अहंकार, विज्ञान आणि डिजिटल युग</span>`,
    "q8": `Q: छायाचित्रण ही कला आणि विज्ञान दोन्ही आहे. तुम्ही याकडे कसे पाहता?`,
    "a8": `A: मी एक सामान्य विद्यार्थी होतो, आणि विज्ञान माझ्या डोक्यात कधीच बसले नाही. त्या मुळे छायाचित्रणाला एक कला म्हणून पाहण्याशिवाय माझ्याकडे पर्याय नाही. आणि ही एक अद्भूत कला आहे. याद्वारे मी बरेच काही मिळवले आहे - सामाजिकरित्या, आर्थिकरित्या आणि कदाचित सर्वात महत्त्वाचे म्हणजे, वैयक्तिक विकासाच्या दृष्टीने. छायाचित्रणाने मला कमळाप्रमाणे अलिप्त राहून काम करायला शिकवले आहे. त्याने मला मी जसा आहे तसाच राहायला शिकवले आहे.
    <br><br>
    पूर्वी, जेव्हा मी एखाद्या सुंदर सूर्योदय, सूर्यास्त किंवा निसर्गचित्राचा फोटो घेऊन परत यायचो, तेव्हा मला एक प्रकारचा अभिमान वाटायचा - की मी काहीतरी अपवादात्मक तयार केले आहे, माझ्याकडे मोठी कलात्मक क्षमता आहे. पण नंतर मला समजले की कोणीही सुंदर सूर्योदय किंवा सूर्यास्ताचा फोटो घेऊ शकतो. त्यात मोठी काही सिद्धी नाही. माझे नशीब हे आहे की मला तिथे उपस्थित राहण्याची संधी मिळाली. मी आसाम, हिमालय अशा ठिकाणी गेलो आहे जिथे बरेच लोक पोहोचू शकत नाहीत.
    <br><br>
    मी जे फोटो परत आणतो ते फक्त एक माध्यम आहेत. त्या अर्थाने मी फक्त एक टपाली आहे, आणि टपालीला पत्र नेण्याचा कोणताही अहंकार नसतो. छायाचित्रकार म्हणून मी फक्त एक माध्यम आहे. सूर्योदय आणि सूर्यास्त स्वतःच अतिशय भव्य आहेत. त्या जाणिवेने माझ्यातील प्रेक्षक अधिक बलवान झाला. एकेकाळी माझ्यात आलेला कोणताही अहंकार हळूहळू नाहीसा झाला. आज जेव्हा माझे विद्यार्थी - सोळा किंवा सतरा वर्षांचे मुले-मुली - त्यांचे फोटो माझ्याकडे आणतात, तेव्हा मला तीच उत्सुकता आणि आश्चर्य जाणवते जे ते अनुभवतात. ती विस्मयाची भावना मला कधीच सोडून गेली नाही.`,
    
    "q9": `Q: तंत्रज्ञानाने छायाचित्रण इतके सोपे केले आहे का की आता कोणीही चांगला फोटो काढू शकतो?`,
    "a9": `A: होय, आणि ते अगदी खरे आहे. आजच्या डिजिटल युगात वाईट फोटो काढण्यासाठीही खूप मेहनत घ्यावी लागते. कॅमेरे इतके प्रगत आहेत की फोटो बहुधा आपोआपच चांगले येतात. तंत्रज्ञानाने संपूर्ण माध्यमच बदलून टाकले. पूर्वी फिल्म असायची, ज्यासोबत वेगवेगळी गती, लोडिंग, शूटिंग, डेव्हलपिंग आणि शेवटी प्रिंट केलेला फोटो हातात धरण्याचा थरार असायचा. डिजिटल तंत्रज्ञानासोबत ते सर्व नाहीसे झाले.
    <br><br>
    पहिला बदल असा झाला की छायाचित्रण स्वस्त झाले. १९८९ किंवा १९९० मध्ये जर तुम्ही ३६ फ्रेमचा रोल शूट केला, तर प्रिंट येईपर्यंत तुमचे सहज सातशे-आठशे रुपये खर्च व्हायचे. छायाचित्रणाच्या विद्यार्थ्यासाठी ती खूप मोठी रक्कम होती. आज तुम्ही तुमचे फोटो ताबडतोब संगणकावर पाहू शकता, त्यामुळे ही प्रक्रिया सोपी आणि स्वस्त दोन्ही झाली आहे. नवीन लेन्समुळे कामही सोपे झाले. मग इंटरनेट आले आणि फोटो पाठवणे खूप सोपे झाले. मी तुम्हाला सेकंदात फोटो पाठवू शकतो.
    <br><br>
    त्यामुळे छायाचित्रकारांसाठी छायाचित्रण सोपे झाले आहे, पण त्याच वेळी स्वतःची गुणवत्ता सिद्ध करणे खूप कठीण झाले आहे कारण स्पर्धा अत्यंत तीव्र आहे. आज जवळजवळ कोणीही चांगला फोटो काढू शकतो. अनेक लोक फेसबुक, इन्स्टाग्राम आणि इतर अनेक प्लॅटफॉर्मवर आकर्षक फोटो पोस्ट करतात. "चांगल्या छायाचित्रकाराचा" एकाधिकार आता संपला आहे. तुम्हाला रोज स्वतःला सिद्ध करावे लागते.`,
    
    "q10": `Q: विज्ञानाच्या प्रगतीमुळे कलेचा हळूहळू मृत्यू झाला आहे का?`,
    "a10": `A: नाही, मी याच्याशी अजिबात सहमत नाही. शेवटी गुजरातीमध्ये एक म्हण आहे: “विहिरीत पाणी असेल तरच ते हौदात येईल.” दुसऱ्या शब्दांत, जर मूळ छायाचित्र मजबूत असेल, तरच एडिटिंग त्याला साथ देऊ शकते. जर मूळ प्रतिमाच कमकुवत असेल, तर एडिटिंग देखील त्याला वाचवू शकत नाही. फोटोशॉप आणि इतर एडिटिंग साधने केवळ पूरक वस्तू आहेत - जसे की दागिने, जसे की मेकअप.
    <br><br>
    नवरी सुंदर सजलेली असू शकते, जड मेकअप आणि दागिने घातलेले असू शकतात, पण तिचे नैसर्गिक सौंदर्यच सर्वात महत्त्वाचे असते. जर ती मुळातच सुंदर असेल, तर ती मेकअपशिवायही सुंदर दिसेल. मेकअप नसलेला चेहरा देखील एक सुंदर चेहरा असू शकतो.`,
    
    "pullquote-4": `"टपालीला पत्र नेण्याचा कोणताही अहंकार नसतो. छायाचित्रकार म्हणून मी फक्त एक माध्यम आहे."`,
    
    "theme-5": `V. ज्ञानाची मशाल सोपवणे <span>शिक्षण, संगीत आणि सर्जनशील उपक्रम</span>`,
    "q11": `Q: तुम्ही छायाचित्रण शिकवण्यात आणि कार्यशाळा आयोजित करण्यात सहभागी आहात. ही कला खरोखर कुठपर्यंत शिकवली जाऊ शकते?`,
    "a11": `A: आता बरेच चांगले आहे. आमच्या काळात छायाचित्रण शिकवणारी कोणतीही संस्था नव्हती. आज अनेक महाविद्यालये आणि संस्था शिकवतात. आणि नवीन उपकरणांमुळे शिकवणेही सोपे झाले आहे. पण मला नेहमीच असे वाटले आहे की छायाचित्रण कधीही बंद खोल्यांमध्ये किंवा केवळ वर्गात शिकता येत नाही. मी महाविद्यालयांमध्ये शिकवतो, पण पहिल्या तीन-चार परिचयात्मक वर्गांनंतर मी सहसा विद्यार्थ्यांना बाहेर घेऊन जातो. आम्ही पाँडिचेरी, आसाम आणि हिमालय अशा ठिकाणी जातो आणि तिथे कार्यशाळा आयोजित करतो.
    <br><br>
    माझे वैयक्तिक मत आहे की विद्यार्थ्यांना अनेक चुका करण्याची परवानगी दिली पाहिजे. मी त्यांना सांगतो की भरपूर चुका करा आणि त्यातून शिका. निसर्ग छायाचित्रण हे असे एक क्षेत्र आहे जिथे चुका लगेच दिसून येतात. चूक निसर्गात नसते, तर तुम्ही ती कशी कॅप्चर करता यात असते. जर तुम्ही ते योग्यरित्या केले नाही, तर त्रुटी दिसून येते. माणूस अशाच प्रकारे शिकतो - स्वतःच्या चुका स्पष्टपणे पाहून. माझा विश्वास आहे की प्रत्येक व्यक्तीच्या आत एक छायाचित्रकार असतो. खरा प्रश्न असा आहे कि तुम्ही त्या अंतर्गत छायाचित्रकाराला किती संधी देता.`,
    
    "q12": `Q: संजय, छायाचित्रणाव्यतिरिक्त तुमचे इतर कोणते छंद आहेत?`,
    "a12": `A: मला वाचन खूप आवडते. माझ्यासाठी वाचन म्हणजे श्वास घेण्यासारखे आहे. मला वाचन करावेच लागते. मला चांगले संगीतही खूप आवडते. वाचन आणि संगीताशिवाय माझे चालत नाही. मला दोघांचीही प्रचंड आवड आहे आणि कदाचित म्हणूनच मी खूप चांगला लेखक किंवा संगीतकार बनू शकलो नाही - कारण मी पुस्तकांचा आणि संगीताचा पूर्णवेळ प्रेमी आहे. मी सर्व काही वाचतो: कथा, कादंबऱ्या, निबंध, पत्रे, कविता - सर्व काही. आणि मी सर्व भाषांमध्ये वाचतो.
    <br><br>
    संगीतात मला भारतीय शास्त्रीय संगीत जास्त आवडते, तरीही मला रॉक बँडबद्दल कोणताही आक्षेप नाही. मला रॉक म्युझिकचाही आनंद मिळतो, जितके मला समजते. माझा मुलगा रॉक आणि जॅझ बँडमध्ये आहे आणि जेव्हा तो मला गोष्टी समजावून सांगतो, शिकवतो आणि दाखवतो तेव्हा मला खूप आवडते. मी संगीताच्या प्रत्येक प्रकाराचे कौतुक करतो, पण शास्त्रीय संगीत मला थोडे अधिक भावते कारण मी ते अधिक चांगल्या प्रकारे समजू शकतो.`,
    
    "q13": `Q: तुम्ही आमच्या अनेक महान संगीतकारांचे फोटो काढले आहेत. तो अनुभव कसा होता?`,
    "a13": `A: होय, मी जवळपास सर्वच प्रमुख भारतीय शास्त्रीय संगीतकारांचे फोटो काढले आहेत. पण खरे सांगायचे तर, मला नेहमीच स्वतःमध्ये एक अपूर्णता जाणवायची कारण मला संगीत माहित नव्हते. मी कलाकारांचे उत्कृष्ट क्षण कॅप्चर करून - त्यांच्या उत्कृष्ट छायाचित्रांद्वारे ती उणीव भरून काढण्याचा प्रयत्न केला.
    <br><br>
    एक प्रकारे, मला माझे काम शक्य तितके काळजीपूर्वक आणि सुंदर करून ती कमतरता भरून काढायची होती. मला संगीत माहित नाही म्हणून मला वाटते की मी असे काहीतरी केले पाहिजे ज्याने संगीतकार मला लक्षात ठेवतील. म्हणून जेव्हा पंडित शिवकुमार शर्मा किंवा उस्ताद झाकीर हुसेन मला फोन करतात आणि म्हणतात, “छायाचित्र खूप छान आले आहे - कृपया ते आम्हाला द्या,” तेव्हा मला असे वाटते की मी एखादा सुंदर राग शिकलो आहे.`,
    
    "q14": `Q: संजय, जर तुम्ही आज एक प्रसिद्ध छायाचित्रकार नसता, तर तुम्हाला काय वाटते तुम्ही काय बनला असता?`,
    "a14": `A: मला वाटते की मी शिक्षक झालो असतो. मला आता तसे वाटते कारण गेल्या अनेक वर्षांपासून मी आधीच अध्यापनात आहे. एक शिक्षक असणे, मार्गदर्शक असणे - विशेषतः आता जेव्हा मी ६० वर्षांचा होत आलो आहे - इतके समाधान देते की जर मी छायाचित्रे घेत नसतो तर नक्कीच शिक्षक झालो असतो.
    <br><br>
    मला विद्यार्थ्यांसोबत राहणे आणि त्यांची ताजेपणा, त्यांची ऊर्जा खूप आवडते. आमचे एक ज्येष्ठ प्राध्यापक सदस्य ख्रिस्तोफर बेनिंगर - एक अमेरिकन वास्तुविशारद जे अनेक वर्षे भारतात राहिले - त्यांनी एकदा आम्हाला एक खूप सुंदर गोष्ट शिकवली होती: “तुम्ही तुमच्या विद्यार्थ्याला देऊ शकता अशी सर्वात मोठी भेट म्हणजे त्याला नेहमी विद्यार्थी राहायला शिकवणे.” ते वाक्य माझ्या मनात घर करून राहिले आहे. ते खूप प्रेरणादायी वाटते. जेव्हा मी शिकवायला जातो तेव्हा दोन-तीन तासांनंतर थकलेला परत येत नाही. मी स्वतः दोन नवीन गोष्टी शिकून, नवीन ऊर्जेसह परत येतो. आणि तेच मला पुढे नेत राहते.`,
    
    "pullquote-5": `"तुम्ही तुमच्या विद्यार्थ्याला देऊ शकता अशी सर्वात मोठी भेट म्हणजे त्याला नेहमी विद्यार्थी राहायला शिकवणे."`
  },
  ml: {
    "sidebar-quote": `"ഓരോ ഛായാചിത്രത്തിന് പിന്നിലും എഴുതപ്പെടാത്ത ഒരു ജീവചരിത്രമുണ്ട്. ഞാൻ അവരുടെ മുഖങ്ങളല്ല ചിത്രീകരിക്കുന്നത്; അവരുടെ സാഹിത്യമാണ്."`,
    "intro-1": `ഗുജറാത്തിലും ഇന്ത്യയിലുടനീളമുള്ള കലാപ്രദർശനങ്ങളിലും നിരവധി ഫോട്ടോ ബുക്കുകളുടെയും കോഫി ടേബിൾ പുസ്തകങ്ങളുടെയും കവറുകളിലും അദ്ദേഹത്തിന്റെ പേര് ദൃശ്യമാകുന്നു. എങ്കിലും ആ ചിത്രങ്ങൾക്ക് പിന്നിലെ സാന്നിധ്യത്തെ പൂർണ്ണമായി വിശേഷിപ്പിക്കാൻ വാക്കുകൾക്ക് പലപ്പോഴും സാധിക്കാറില്ല — തന്റെ ലെൻസിലൂടെ ദൃശ്യങ്ങളെയും മുഖങ്ങളെയും സംസാരിപ്പിക്കുന്ന ഒരു ഛായാഗ്രാഹകൻ, ഈ കലയിലെ ശാന്തനായ ഒരു പ്രതിഭ, ക്യാമറയേന്തിയ കവി: <strong>സഞ്ജയ് വൈദ്യ</strong>.`,
    "intro-2": `2007 മുതൽ അദ്ദേഹത്തിന്റെ സവിശേഷമായ ഫോട്ടോ പുസ്തകങ്ങൾ പതിവായി പ്രസിദ്ധീകരിക്കപ്പെടുന്നുണ്ട്, പ്രത്യേകിച്ച് പ്രശസ്ത വ്യക്തികളെക്കുറിച്ചുള്ള അദ്ദേഹത്തിന്റെ പോർട്രെയ്റ്റ് പരമ്പരകൾ. ഈ പുസ്തകങ്ങൾ പലപ്പോഴും ഫോട്ടോഗ്രാഫുകളുടെ ഒരു ശേഖരം എന്നതിലുപരി, അവയിൽ പകർത്തിയിരിക്കുന്ന വ്യക്തികളുടെ ആത്മബന്ധമുള്ള ദൃശ്യസ്മരണകളായി അനുഭവപ്പെടുന്നു. അവ അദ്ദേഹത്തിന് വ്യാപകമായ അംഗീകാരവും ഇന്ത്യയിലെ പ്രമുഖ ഫോട്ടോഗ്രാഫർമാർക്കിടയിൽ ഒരു സ്ഥാനവും നേടിക്കൊടുത്തു. <br><br> അദ്ദേഹം ചിത്രീകരിച്ചിട്ടുള്ള നിരവധി ഐതിഹാസിക വ്യക്തികളിൽ ഗുജറാത്തി സാഹിത്യത്തിലെ അതികായന്മാരായ <em>സുരേഷ് ദലാൽ, താരക് മേത്ത, ചന്ദ്രകാന്ത് ബക്ഷി, ഗുണവന്ത് ഷാ</em> എന്നിവരും; ഇന്ത്യൻ ക്ലാസിക്കൽ സംഗീതത്തിലെ പ്രഗത്ഭരായ <em>പണ്ഡിറ്റ് ഭീംസെൻ ജോഷി, പണ്ഡിറ്റ് ജസ്രാജ്, പണ്ഡിറ്റ് ശിവകുമാർ ശർമ്മ, ഉസ്താദ് അംജദ് അലി ഖാൻ, ബീഗം പർവീൺ സുൽത്താന, പണ്ഡിറ്റ് ഹരിപ്രസാദ് ചൗരസ്യ, പണ്ഡിറ്റ് രാജൻ-സാജൻ മിശ്ര, ഉസ്താദ് സക്കീർ ഹുസൈൻ</em>, ഗ്രാമി ജേതാവ് <em>പണ്ഡിറ്റ് വിശ്വ മോഹൻ ഭട്ട്</em> എന്നിവരും; ആത്മീയ നേതാക്കളായ <em>മൊരാരി ബാപ്പു, ശ്രീ ശ്രീ രവിശങ്കർ, പ്രമുഖ് സ്വാമി മഹാരാജ്</em>, <em>രമേഷ്ഭായ് ഓജ</em> എന്നിവരും; ചലച്ചിത്ര രംഗത്തെ പ്രമുഖരായ <em>ഗുൽസാർ, അമിതാഭ് ബച്ചൻ, ഐശ്വര്യ റായ് ബച്ചൻ, ആശാ ബോസ്‌ലെ, മനോജ് ബാജ്പേയ്, തബു</em>, <em>ഇർഫാൻ ഖാൻ</em> എന്നിവരും ഉൾപ്പെടുന്നു.`,
    "intro-3": `അഹമ്മദാബാദ് ആസ്ഥാനമായി പ്രവർത്തിക്കുന്ന സഞ്ജയ് ഫോട്ടോഗ്രാഫി പഠിപ്പിക്കുകയും വർക്ക്‌ഷോപ്പുകൾ നടത്തുകയും ക്രിയേറ്റീവ് വിഷ്വಲ್ സ്റ്റോറിടെല്ലിംഗ് പര്യവേക്ഷണം ചെയ്യുകയും ചെയ്യുന്നു. ഭാഷയോടും സാഹിത്യത്തോടുമുള്ള അദ്ദേഹത്തിന്റെ ആഴത്തിലുള്ള സ്നേഹം സാഹിത്യ പ്രസിദ്ധീകരണങ്ങളിലേക്കും, സംസ്കൃത നാടോടി സംഗീത ഫ്യൂഷനുകളിലേക്കും പ്രശസ്തരായ ഗുജറാത്തി എഴുത്തുകാരെക്കുറിച്ചുള്ള ഡോക്യുമെന്ററി നിർമ്മാണങ്ങളിലേക്കും അദ്ദേഹത്തെ ആകർഷിച്ചു. ഒരു അഭിമുഖത്തിനായി സമീപിച്ചപ്പോൾ, അദ്ദേഹം തന്റെ പതിവ് വിനയത്തോടെ പ്രതികരിച്ചു: <em>"എനിക്ക് സംസാരിക്കാൻ അത്ര നന്നായി അറിയില്ല,"</em> തുടർന്ന് ഈ സംഭാഷണം ആരംഭിച്ചു.`,
    
    "theme-1": `I. ഒരു നിയോഗത്തിന്റെ തുടക്കം <span>തുടക്കവും തൊഴിലും</span>`,
    "q1": `Q: സഞ്ജയ്, ഫോട്ടോഗ്രാഫിയിലുള്ള ഈ അപൂർവ്വമായ താല്പര്യം എവിടെ നിന്നാണ് ഉണ്ടായത്, അത് എങ്ങനെയാണ് വളർന്നത്?`,
    "a1": `A: ഫോട്ടോഗ്രാഫി എപ്പോഴും എന്റെ അഭിനിവേശവും ഹോബിയുമായിരുന്നു. ഞാൻ ഇത് ഒരു പ്രൊഫഷനായി സ്വീകരിക്കുമെന്ന് ഒരിക്കലും കരുതിയിരുന്നില്ല. ഞാൻ എപ്പോഴും പ്രകൃതിയെ സ്നേഹിക്കുകയും എന്റെ ചുറ്റും നടക്കുന്ന എല്ലാ കാര്യങ്ങളിലും താല്പര്യം കാണിക്കുകയും ചെയ്തിരുന്നു. ചെറുപ്പത്തിൽപ്പോലും, സംഭവങ്ങൾ നടക്കുന്നത് ഞാൻ കാണുന്നുണ്ടെങ്കിലും, ഞാൻ പൂർണ്ണമായും അവയുടെ ഉള്ളിലല്ല എന്ന് എനിക്ക് തോന്നാറുണ്ടായിരുന്നു. എവിടെയൊക്കെയോ എനിക്ക് അതിൽ പങ്കാളിയാകാൻ തോന്നി. ഒരു നിമിഷം കാണാനും അത് ഫ്രീസ് ചെയ്യാനും ആഗ്രഹിക്കുന്ന എന്തോ ഒന്ന് എപ്പോഴും എന്നിൽ ഉണ്ടായിരുന്നു എന്ന് ഞാൻ കരുതുന്നു. ഞാൻ ആദ്യമായി ഒരു ക്യാമറ കൈയിലെടുത്ത് ആദ്യത്തെ ചില ഫോട്ടോഗ്രാഫുകൾ എടുത്തപ്പോൾ തന്നെ, ഇതാണ് ഞാൻ ചെയ്യാൻ ആഗ്രഹിക്കുന്നതെന്ന് എനിക്കറിയാമായിരുന്നു. ഞാൻ അസമിലോ മറ്റെവിടെയെങ്കിലുമോ പോയാലും, എന്തെങ്കിലും കാണാനും അത് ഫോട്ടോ എടുക്കാനും അത് തിരികെ കൊണ്ടുവരാനുമുള്ള പ്രക്രിയ ഞാൻ ഇഷ്ടപ്പെട്ടിരുന്നു. ആ അനുഭവം എനിക്ക് അളവറ്റ സന്തോഷം നൽകി. അങ്ങനെയാണ് ഞാൻ ഈ രംഗത്തേക്ക് കടന്നുവന്നത്.`,
    
    "q2": `Q: ഫോട്ടോഗ്രാഫി ഒരു ഹോബിയായി കൊണ്ടുനടക്കുന്നത് ഒരു കാര്യമാണ്, എന്നാൽ ഇത് ഒരു തൊഴിലായി സ്വീകരിക്കുന്നത് അപകടസാധ്യത നിറഞ്ഞതായിരുന്നില്ലേ? ഒരു പുതിയ ഫോട്ടോഗ്രാഫർക്ക് ഇതിന്റെ സാമ്പത്തിക വശം എങ്ങനെയാണ് പ്രവർത്തിക്കുന്നത്?`,
    "a2": `A: ഇത് തീർച്ചയായും അപകടസാധ്യതയുള്ളതായി തോന്നിയിരുന്നു. എന്റെ കുടുംബത്തിൽ എന്റെ മുത്തശ്ശി പറയാറുണ്ടായിരുന്നു, “നീ എത്ര നാൾ ഈ ഫോട്ടോ എടുക്കൽ തുടരും? ആരെങ്കിലും വിവാഹാലോചനയുമായി വന്ന് പയ്യൻ എന്താണ് ചെയ്യുന്നതെന്ന് ചോദിച്ചാൽ നമ്മൾ എന്ത് പറയും — അവൻ പടം പിടിക്കുകയാണെന്നോ?” ആ കാലത്ത് ഫോട്ടോഗ്രാഫി പലപ്പോഴും ഒരു താഴ്ന്ന ജോലിയായാണ് കണക്കാക്കപ്പെട്ടിരുന്നത്. ഞാൻ ഒരിക്കലും ഒരു മിടുക്കനായ വിദ്യാർത്ഥിയായിരുന്നില്ല, എന്റെ പഠനനിലവാരം വളരെ ശരാശരിയായിരുന്നു. അതിനാൽ ഒരു ഡോക്ടറോ എഞ്ചിനീയറോ ആകണമെന്ന ആഗ്രഹമൊന്നും എനിക്കുണ്ടായിരുന്നില്ല. ഞാൻ ആദ്യം ഫോട്ടോഗ്രാഫി ഒരു ഹോബിയായി സ്വീകരിച്ചു, പിന്നീട് അറിയാതെ തന്നെ അത് എന്റെ പ്രൊഫഷനായി മാറി.
    <br><br>
    ആ കാലങ്ങളിൽ ഫോട്ടോഗ്രാഫിയുടെ സാമ്പത്തിക വശം വളരെ വ്യത്യസ്തമായിരുന്നു. പെയിന്റിംഗുമായി താരതമ्यപ്പെടുത്തുമ്പോൾ, ഫോട്ടോഗ്രാഫി ഒരു താഴ്ന്ന കലാരൂപമായാണ് കണക്കാക്കപ്പെട്ടിരുന്നത് — വാസ്തവത്തിൽ, പലരും ഇതിനെ ഒരു കലയായി പോലും അംഗീകരിച്ചിരുന്നില്ല. സൗന്ദര്യാത്മക എന്നതിനേക്കാൾ ഇതൊരു സാങ്കേതിക കാര്യമായാണ് കാണപ്പെട്ടിരുന്നത്. പിന്നീട് ഡിജിറ്റൽ സാങ്കേതികവിദ്യയുടെ വരവോടെ ഈ മാധ്യമം നാടകീയമായി മാറി. അതിനുമുമ്പ് തന്നെ, ഫിലിം ഫോട്ടോഗ്രാഫിയിലൂടെയും പിന്നീട് ടെലിവിഷൻ, സിനിമ എന്നിവയിലൂടെയും, പ്രത്യേകിച്ച് 1990-കൾക്ക് ശേഷം ഫോട്ടോഗ്രാഫിക്ക് വലിയ അംഗീകാരം ലഭിച്ചു. അതിന്റെ സാമ്പത്തിക മൂല്യവും മാറി. ഇന്ന് ഫോട്ടോഗ്രാഫർമാർക്ക് എത്രമാത്രം പണം സമ്പാദിക്കാൻ കഴിയുമെന്ന് ഊഹിക്കാൻ പോലും കഴിയില്ല. ഇന്ത്യയിൽ പല ഫോട്ടോഗ്രാഫർമാരും ഇപ്പോൾ സിനിമകളിലെയും ടെലിവിഷൻ സീരിയലുകളിലെയും ക്യാമറാമാൻമാരേക്കാൾ കൂടുതൽ സമ്പാദിക്കുന്നുണ്ട്.`,
    
    "pullquote-1": `"ഓരോ ഫോട്ടോയും ജനിക്കുന്നത് സെക്കൻഡിന്റെ എട്ടിലൊരു ഭാഗത്തിലാണ്."`,
    
    "theme-2": `II. നിമിഷങ്ങളുടെ കല <span>നിമിഷങ്ങൾ, ചിത്രകല & വെളിച്ചം</span>`,
    "q3": `Q: താങ്കൾ ഒരു ചിത്രകാരൻ കൂടിയാണ്. ഒരു ഫോട്ടോഗ്രാഫർ ഉണ്ടാക്കുന്ന ചിത്രവും ഒരു ചിത്രകാരൻ വരയ്ക്കുന്ന ചിത്രവും തമ്മിലുള്ള വ്യത്യാസം എന്താണ്?`,
    "a3": `A: ഞാൻ ഒരു ഫോട്ടോഗ്രാഫർ ആയതുകൊണ്ട് ഫോട്ടോഗ്രാഫിയാണ് മഹത്തരമെന്ന് ഞാൻ പറയരുത്. എന്നാൽ സത്യസന്ധമായി പറഞ്ഞാൽ, നിങ്ങൾ വരയ്ക്കുമ്പോൾ നിങ്ങൾക്ക് ആ സൃഷ്ടിയിൽ മാറ്റങ്ങൾ വരുത്താനുള്ള സ്വാതന്ത്ര്യമുണ്ടെന്ന് എനിക്ക് എപ്പോഴും തോന്നിയിട്ടുണ്ട്. എന്തെങ്കിലും ശരിയായില്ലെങ്കിൽ, നിങ്ങൾക്ക് അതിന്റെ രൂപവും നിറവുമെല്ലാം മാറ്റാം. ആ സ്വാതന്ത്ര്യം ചിത്രരചനയിലുണ്ട്. എന്നാൽ ഫോട്ടോഗ്രാഫിയിൽ അത്തരം സ്വാതന്ത്ര്യമില്ല. നിങ്ങൾ ഒരു നിമിഷം പകർത്തി അത് സൂക്ഷിക്കണം. അത് നഷ്ടപ്പെട്ടാൽ കഴിഞ്ഞു. അതിനാൽ നിങ്ങൾ എപ്പോഴും ജാഗരൂകരായിരിക്കണം, ആ നിമിഷം വരുന്നതിന് മുമ്പ് തന്നെ അത് തിരിച്ചറിയണം, എന്നിട്ട് കൃത്യമായ നിമിഷത്തിൽ ക്ലിക്ക് ചെയ്യണം. സൽമാൻ റുഷ്ദി ഒരിക്കൽ പറഞ്ഞ മനോഹരമായ ഒരു വരിയുണ്ട്: "ഓരോ ഫോട്ടോയും ജനിക്കുന്നത് സെക്കൻഡിന്റെ എട്ടിലൊരു ഭാഗത്തിലാണ്." ഞാൻ അതിനെ അങ്ങനെയാണ് കാണുന്നത്. ആ ചെറിയ സമയത്തിനുള്ളിൽ, നിങ്ങളുടെ ഫോട്ടോ എത്രത്തോളം ശക്തമാണെന്ന് നിങ്ങൾ തെളിയിക്കണം.`,
    
    "q4": `Q: താങ്കൾ പ്രകൃതി ഫോട്ടോഗ്രാഫിയിലൂടെയാണ് തുടങ്ങിയത്, എന്നാൽ ഇന്ന് അറിയപ്പെടുന്നത് പോർട്രെയ്റ്റ് ഫോട്ടോഗ്രാഫർ എന്ന നിലയിലാണ്. ആ യാത്ര എങ്ങനെയായിരുന്നു?`,
    "a4": `A: subtleties തുടക്കത്തിൽ അധികം ഓപ്ഷനുകൾ ഇല്ലായിരുന്നു. വന്യജീവി, പ്രകൃതി, കാൻഡിഡ് അല്ലെങ്കിൽ പോർട്രെയ്റ്റ് ഫോട്ടോഗ്രാഫി എന്ന രീതിയിലുള്ള വലിയ വേർതിരിവുകളൊന്നും അന്ന് ഉണ്ടായിരുന്നില്ല. ഗുജറാത്തിലോ അഹമ്മദാബാദിലോ ഫോട്ടോഗ്രാഫി പഠിപ്പിക്കുന്ന സ്ഥാപനങ്ങളും ഉണ്ടായിരുന്നില്ല. തെറ്റുകളിൽ നിന്നാണ് ഞാൻ പഠിച്ചത്. ആദ്യം ക്യാമറ വാങ്ങണം, പിന്നെ ഫിലിം റോളുകൾ, പിന്നെ ചിത്രങ്ങൾ എടുക്കുക, എന്നിട്ട് പരിചയസമ്പന്നരായ ആരോടെങ്കിലും കാണിക്കുക — അവർ നല്ല മൂഡിലാണെങ്കിൽ ചില കാര്യങ്ങൾ പറഞ്ഞു തന്നേക്കാം. പ്രധാന നിയമം ലളിതമായിരുന്നു: ഒരിക്കൽ വരുത്തിയ തെറ്റ് വീണ്ടും ആവർത്തിക്കരുത്.
    <br><br>
    ലാൻഡ്‌സ്‌കേപ്പുകൾ കൂടുതൽ എളുപ്പമായിരുന്നു, കാരണം അവയിൽ വൈവിധ്യമുണ്ടായിരുന്നു — വ്യത്യസ്ത മരങ്ങൾ, വ്യത്യസ്ത തടാകങ്ങൾ, വ്യത്യസ്ത ദൃശ്യങ്ങൾ. മുഖങ്ങളിലേക്കുള്ള എന്റെ മാറ്റം അറിവില്ലാതെ സംഭവിച്ചതാണ്. ഞാൻ മനപ്പൂർവ്വം പോർട്രെയ്റ്റുകളിലേക്ക് മാറാൻ തീരുമാനിച്ചതല്ല. എന്നാൽ മുന്നോട്ട് പോയപ്പോൾ, പ്രകൃതിദൃശ്യങ്ങൾ നൽകുന്ന അതേ വൈവിധ്യം മനുഷ്യമുഖങ്ങളും നൽകുന്നുണ്ടെന്ന് എനിക്ക് മനസ്സിലായി. ഞാൻ 40 വർഷമായി ഫോട്ടോ എടുക്കുന്നു, ഇതുവരെ ഒരേപോലെയുള്ള രണ്ട് മുഖങ്ങൾ ഞാൻ കണ്ടിട്ടില്ല. ഇരട്ടക്കുട്ടികൾ പോലും എനിക്ക് ഒരേപോലെ തോന്നാറില്ല. ഇത്രയധികം മുഖങ്ങളിലൂടെ കടന്നുപോകുന്നത് അസാധാരണമായ ഒരു അനുഭവമാണ്.
    <br><br>
    ഓരോ മുഖവും ഒരു കഥ വഹിക്കുന്നുണ്ട്, അതിന്റേതായ ഒരു ഒപ്പ് അതിലുണ്ട്. ആ കഥ കണ്ടെത്തുന്നത് ഒരു സന്തോഷമാണ്. അതിൽ അപകടസാധ്യതയുണ്ട്, എങ്കിലും ആവേശവും ആനന്ദവുമുണ്ട്. ഒരു വ്യക്തിയുടെ മുഖത്തിന് പിന്നിലെ കഥ പുറത്തുകൊണ്ടുവരാൻ കഴിഞ്ഞാൽ, നിങ്ങൾ വിജയിച്ചു. അല്ലെങ്കിൽ ഫോട്ടോ എത്ര ആകർഷകമാണെങ്കിലും അത് വെറും ഉപരിപ്ലവമായി അവശേഷിക്കും. ഒരു പോർട്രെയ്റ്റ് ആ വ്യക്തിയുടെ ആന്തരികത വെളിപ്പെടുത്തണം. അതുകൊണ്ടാണ് ചിത്രമെടുക്കുന്നതിന് മുൻപ് അവരെ നേരിൽ കാണാൻ ഞാൻ ആഗ്രഹിക്കുന്നത്. അടുത്ത ദിവസം ഒരാളുടെ ഫോട്ടോ എടുക്കണമെന്നുണ്ടെങ്കിൽ പോലും, ഞാൻ ആദ്യം അവരുടെ കൂടെ രണ്ടോ മൂന്നോ മണിക്കൂർ ചെലവഴിക്കാൻ ഇഷ്ടപ്പെടുന്നു — വെറും സാധാരണ സംഭാഷണം മാത്രം, ഔദ്യോഗികമായി ഒന്നുമില്ല. ആ സമയത്ത് ഞാൻ അവരുടെ മുഖം ശ്രദ്ധാപൂർവ്വം നിരീക്ഷിക്കും. അവരുടെ ഇഷ്ടാനിഷ്ടങ്ങൾ നോക്കും, മുഖത്തിന്റെ ഏത് വശമാണ് കൂടുതൽ സത്യസന്ധമായി സംസാരിക്കുന്നതെന്ന് മനസ്സിലാക്കാൻ ശ്രമിക്കും. കണ്ണുകൾ അത്ഭുതകരമാംവിധം സത്യസന്ധമാണെന്ന് ഞാൻ കണ്ടെത്തിയിട്ടുണ്ട്. നമ്മുടെ ജോലി ലെൻസ് കൊണ്ടാണെന്നതിനാൽ നമ്മളും സത്യസന്ധരായിരിക്കണം.`,
    
    "q5": `Q: പോർട്രെയ്റ്റുകൾക്കായി ചിത്രമെടുക്കേണ്ട വ്യക്തികളെ താങ്കൾ എങ്ങനെയാണ് തിരഞ്ഞെടുക്കുന്നത്?`,
    "a5": `A: ഇപ്പോൾ എനിക്ക് തിരഞ്ഞെടുക്കാനുള്ള സ്വാതന്ത്ര്യമുണ്ട്. മുൻപ് ഞാൻ ഒരു വാണിജ്യ ഫോട്ടോഗ്രാഫർ ആയിരുന്നു, അതിനാൽ പണം നൽകുന്ന ആരുടെയും ഫോട്ടോ എടുക്കുമായിരുന്നു. ഇന്ന് എനിക്ക് 'വേണ്ട' എന്ന് പറയാൻ കഴിയും. എനിക്ക് ഒരാളുടെ ഫോട്ടോ എടുക്കാൻ താല്പര്യംമില്ലെന്നോ അല്ലെങ്കിൽ അത് ചെയ്യാൻ എനിക്ക് ബുദ്ധിമുട്ടുണ്ടെന്നോ പറയാം. എനിക്ക് ഒരു നായകനല്ലാത്ത ആളെയോ അല്ലെങ്കിൽ വിചിത്ര സ്വഭാവമുള്ള ഒരാളെയോ ചിത്രീകരിക്കാം, എന്നാൽ ഒരു വില്ലനെ എനിക്ക് ചിത്രീകരിക്കാൻ കഴിയില്ല. ഒരു വ്യക്തി ഉള്ളിലൊന്ന് പുറത്തൊന്ന് കാണിക്കുന്നയാളാണെന്ന് തോന്നിയാൽ, എനിക്ക് അവരുടെ ഫോട്ടോ എടുക്കാൻ കഴിയില്ല. ഒരു മുഖം മുഖംമൂടി ധരിച്ചിരിക്കുമ്പോൾ ആ കൃത്രിമത്വം എനിക്ക് വ്യക്തമായി കാണാം, ഫോട്ടോഗ്രാഫിയിലൂടെ ആ മുഖംമൂടി മാറ്റാൻ എനിക്ക് കഴിയില്ല. അത് എന്നെ അലട്ടുന്നു. അതിനാൽ ഞാൻ അത്തരം ആളുകളുടെ ഫോട്ടോ എടുക്കാൻ താല്പര്യപ്പെടുന്നില്ല. തീർച്ചയായും ഇത് എന്റെ വ്യക്തിപരമായ കാഴ്ചപ്പാടാണ്. ഞാൻ കൃത്രിമമായി കാണുന്ന ഒരാൾ മറ്റൊരാളുടെ കണ്ണിൽ അങ്ങനെയാകണമെന്നില്ല.`,
    
    "pullquote-2": `"ഓരോ മുഖവും ഒരു കഥ വഹിക്കുന്നുണ്ട്, അതിന്റേതായ ഒരു ഒപ്പ് അതിലുണ്ട്. ആ കഥ കണ്ടെത്തുന്നത് ഒരു സന്തോഷമാണ്."`,
    
    "theme-3": `III. കൂടിക്കാഴ്ചകളും അനുഭവങ്ങളും <span>മൊരാരി ബാപ്പുവും അമർനാഥിലെ അപകടവും</span>`,
    "q6": `Q: താങ്കൾ നിരവധി പോർട്രെയ്റ്റ് പുസ്തകങ്ങൾ ചെയ്തിട്ടുണ്ട്. ഏത് വ്യക്തികളോടൊപ്പമാണ് പ്രവർത്തിക്കാൻ ഏറ്റവും കൂടുതൽ താല്പര്യം തോന്നിയിട്ടുള്ളത്? ഓർമ്മയിൽ നിൽക്കുന്ന അനുഭവങ്ങൾ എന്തെങ്കിലും ഉണ്ടോ?`,
    "a6": `A: ഞാൻ വ്യത്യസ്ത മേഖലകളിൽ നിന്നുള്ള നിരവധി ആളുകളോടൊപ്പം സമയം ചെലവഴിക്കാൻ എനിക്ക് ഭാഗ്യം ലഭിച്ചിട്ടുണ്ട്, പലപ്പോഴും മണിക്കൂറുകൾ മാത്രമല്ല രണ്ട് മൂന്ന് ദിവസങ്ങൾ തുടർച്ചയായി. ഒരു അനുഭവം മാത്രം എടുത്തുപറയുക പ്രയാസമാണ്. എങ്കിലും മൊരാരി ബാപ്പുവിന്റെ ഫോട്ടോ ബുക്കിനായി പ്രവർത്തിച്ച സമയത്തെ ഒരു ഓർമ്മ ഇന്നും മനസ്സിൽ പച്ചപിടിച്ചു നിൽക്കുന്നു.
    <br><br>
    അദ്ദേഹത്തെ ചിത്രീകരിക്കാൻ ഞാൻ ജഗന്നാഥ പുരിയിൽ പോയിരുന്നു. അവിടെയുള്ള അന്തരീക്ഷവും സംസ്കാരവുമെല്ലാം തികച്ചും വ്യത്യസ്തമായിരുന്നു, എന്നെ ആർക്കും അറിയുകയുമില്ലായിരുന്നു. ബാപ്പുവിന് ചുറ്റും നിരവധി ആളുകൾ ഉണ്ടായിരുന്നതിനാൽ എനിക്ക് അദ്ദേഹത്തിന്റെ അടുത്തേക്ക് പോകാൻ കഴിഞ്ഞില്ല. അദ്ദേഹം എന്നെ കാണുമ്പോൾ വിളിക്കുമെന്ന് ഞാൻ കരുതി, എന്നാൽ അദ്ദേഹത്തിലേക്ക് എത്താൻ നിരവധി തടസ്സങ്ങൾ മറികടക്കേണ്ടതുണ്ടായിരുന്നു. അങ്ങനെ ഞാൻ രണ്ട് ദിവസം കാത്തിരുന്നു. മൂന്നാം ദിവസം ഞാൻ എങ്ങനെയൊക്കെയോ അദ്ദേഹത്തിന്റെ അടുത്തേക്ക് എത്തിപ്പെട്ടു.
    <br><br>
    എന്നെ കണ്ടപ്പോൾ അദ്ദേഹം അരികിലേക്ക് വിളിച്ച് ചോദിച്ചു, "മകനേ, നീ എങ്ങനെ ഇവിടെയെത്തി?" ഞാൻ പറഞ്ഞു, "ബാപ്പു, എനിക്ക് താങ്കളുടെ ഫോട്ടോകൾ എടുക്കണം. ഞാൻ ഒരു ഫോട്ടോ ബുക്ക് ചെയ്യുകയാണ്, എനിക്ക് രാവിലെ മുതൽ വൈകുന്നേരം വരെ താങ്കളുടെ കൂടെയുണ്ടാകണം." ആ സമയത്ത് അദ്ദേഹത്തിന് ചുറ്റും അൻപതോ അറുപതോ പേരുണ്ടായിരുന്നു, കാൽക്കൽ വീണ് വന്ദിക്കാത്തതിനും ഇത്രയും സാധാരണമായി സംസാരിച്ചതിനും അവരെല്ലാം എന്നെ ശാസിച്ചു. എന്നാൽ എനിക്ക് അദ്ദേഹത്തെ കുട്ടിക്കാലം മുതലേ അറിയാമായിരുന്നു. ഔപചാരികമായ ഇത്തരം കാര്യങ്ങളൊന്നും എനിക്ക് ആവശ്യമായി തോന്നിയില്ല. അദ്ദേഹം എന്നേക്കാൾ പ്രായമുള്ളയാളാണ്, ഞാൻ മുതിർന്നവരെ ബഹുമാനിക്കുന്നുമുണ്ട്. അത് നമ്മുടെ സംസ്കാരത്തിന്റെ ഭാഗമാണ്. എന്നാൽ ഒരാൾ ആത്മീയ നേതാവായതുകൊണ്ട് ഞാൻ സാഷ്ടാംഗം പ്രണമിക്കണമെന്ന് എനിക്ക് തോന്നുന്നില്ല. ഞാൻ പറയുന്നത് തെറ്റായിരിക്കാം, എങ്കിലും ഞാൻ ഫോട്ടോ എടുത്ത ഒരു ആത്മീയ നേതാവും ഇതിൽ എതിർപ്പ് പ്രകടിപ്പിച്ചിട്ടില്ല. മൊരാരി ബാപ്പുവാകട്ടെ, രമേഷ്ഭായ് ഓജയാകട്ടെ, ശ്രീ ശ്രീ രവിശങ്കറാകട്ടെ, ആരും തന്നെ എന്തുകൊണ്ട് അവരുടെ കാൽക്കൽ വീണില്ല എന്ന് ചോദിച്ചിട്ടില്ല.
    <br><br>
    പിറ്റേദിവസം നാലുമണിക്ക് ഞാൻ വീണ്ടും വിളിക്കപ്പെട്ടപ്പോൾ നേരിയ ചാറ്റൽ മഴയുണ്ടായിരുന്നു. ബാപ്പുവിന്റെ മുറിയിലേക്ക് പോയപ്പോൾ കോണിപ്പടികളും മുറ്റവുമെല്ലാം ആളുകളെക്കൊണ്ട് നിറഞ്ഞിരുന്നു. എന്നെപ്പോലെയുള്ള ഒരാൾ ഒരു സന്യാസിയെ ശല്യപ്പെടുത്തരുതെന്നും അദ്ദേഹത്തിന്റെ ധ്യാനത്തിന് തടസ്സം നിൽക്കരുതെന്നും പറഞ്ഞ് അവിടെയുള്ള ആളുകൾ എന്നെ കുറ്റപ്പെടുത്തുന്നുണ്ടായിരുന്നു. ഒരു നിമിഷം ഞാൻ തെറ്റാണ് ചെയ്യുന്നതെന്ന് എനിക്ക് തോന്നിപ്പോയി. എന്നാൽ അദ്ദേഹത്തെ കണ്ട മാത്രയിൽ ആ സംശയം മാറിപ്പോയി. അദ്ദേഹം എന്നോട് പറഞ്ഞു, "ഞാൻ എന്റെ ജോലി ചെയ്യുന്നു, നീ നിന്റെ ജോലി ചെയ്യ്." തുടർന്ന് അദ്ദേഹം തന്റെ പതിവ് കർമ്മങ്ങൾ തുടർന്നു — സൂര്യന് വെള്ളം സമർപ്പിക്കുക, തുളസി ചെടി നനയ്ക്കുക — എല്ലാറ്റിന്റെയും മനോഹരമായ ചിത്രങ്ങൾ എടുക്കാൻ അദ്ദേഹം എന്നെ അനുവദിച്ചു. Within ഇരുപത്തിയഞ്ച് മിനിറ്റിനുള്ളിൽ ഞാൻ നൂറ്റിയൻപതോളം ചിത്രങ്ങൾ എടുത്തു. അദ്ദേഹം ഒട്ടും എതിർപ്പ് പ്രകടിപ്പിച്ചില്ല.`,
    
    "q7": `Q: തീർച്ചയായും താങ്കൾക്ക് ബുദ്ധിമുട്ടേറിയ സാഹചര്യങ്ങളും നേരിടേണ്ടി വന്നിട്ടുണ്ടാകുമല്ലോ.`,
    "a7": `A: അതെ, തീർച്ചയായും. എനിക്ക് കൃത്യമായ വർഷം ഓർമ്മയില്ല, എങ്കിലും 1998 ആണെന്ന് തോന്നുന്നു, അമർനാഥിൽ ഉരുൾപൊട്ടലുണ്ടാവുകയും നാലായിരത്തോളം ആളുകൾ മരിക്കുകയും ചെയ്ത സമയം. ഞാൻ അപ്പോൾ മുംബൈയിലായിരുന്നു, അവിടെപ്പോയി ചിത്രങ്ങൾ എടുക്കാൻ എനിക്ക് നിർദ്ദേശം ലഭിച്ചു. ചീഫ് എഡിറ്റർ ഹർകിഷൻ മേത്ത എന്നെ വിളിച്ചു — ഞാൻ വളരെയധികം ബഹുമാനിക്കുന്ന വ്യക്തിയാണ് അദ്ദേഹം — മറ്റുള്ളവരെല്ലാം വിസമ്മതിക്കുന്നതിനാൽ ഞാൻ പോകണമെന്ന് അദ്ദേഹം പറഞ്ഞു. സാഹചര്യം വളരെ കഠിനമാണെന്ന് അവർക്ക് തോന്നിയിരുന്നു. ഞാൻ പോകുമോ എന്ന് അദ്ദേഹം ചോദിച്ചു. എനിക്ക് ചെറുപ്പത്തിന്റെ ആവേശമുണ്ടായിരുന്നു. എല്ലാവരും 'വേണ്ട' എന്ന് പറഞ്ഞപ്പോൾ എനിക്ക് അതിനോട് താല്പര്യം കൂടി. അങ്ങനെ ഞാൻ പോയി.
    <br><br>
    മുംബൈയിൽ നിന്ന് ഞാൻ അഹമ്മദാബാദിലേക്കും അവിടെ നിന്ന് ഡൽഹിയിലേക്കും പിന്നീട് ശ്രീനഗറിലേക്കും പോയി. ശ്രീനഗറിൽ നിന്ന് സൈന്യം ഞങ്ങളെ ഹെലികോപ്റ്ററിൽ ശേഷ്നാഗിലേക്ക് കൊണ്ടുപോയി. അവിടെ വിദേശ മാധ്യമപ്രവർത്തകരും ഉണ്ടായിരുന്നു, എങ്കിലും ഞാൻ ഒരു ഇന്ത്യക്കാരനായതിനാൽ എനിക്ക് ആദ്യം ഹെലികോപ്റ്ററിൽ പോകാൻ അവസരം ലഭിച്ചു. ഇത്രയും പ്രധാനപ്പെട്ട ഒരു വാർത്ത റിപ്പോർട്ട് ചെയ്യാൻ അവസരം ലഭിച്ചതിൽ ഞാൻ സന്തോഷിച്ചു. എന്നാൽ അവിടെ ഇറങ്ങി ചുറ്റുമുള്ള കാഴ്ച കണ്ടപ്പോൾ അത് ഭയാനകമായിരുന്നു. ഫോട്ടോകൾ എടുക്കുമ്പോൾ ഞാൻ വിറയ്ക്കുന്നുണ്ടായിരുന്നു — തണുപ്പ് കൊണ്ടല്ല, മറിച്ച് ആ കാഴ്ചയുടെ ഭീകരത കൊണ്ടാണ്.
    <br><br>
    തിരിച്ചുപോരുമ്പോൾ ഹെലികോപ്റ്ററിൽ പൈലറ്റും മറ്റൊരാളും ഞാനും മാത്രമാണുണ്ടായിരുന്നത്. പിന്നീട് അവർ അതിലേക്ക് മൃതദേഹങ്ങൾ കയറ്റി. ഇരുപതോളം മൃതദേഹങ്ങൾ ഒന്നിനു മീതെ ഒന്നായി അടുക്കിവെച്ചിട്ടുണ്ടായിരുന്നു. ഹെലികോപ്റ്റർ ഉയരുമ്പോൾ അവയോട് ചേർന്നുനിൽക്കേണ്ടി വന്നു, ആ അവസ്ഥയിലാണ് ഞാൻ ജനാലയിലൂടെ ആകാശദൃശ്യങ്ങൾ പകർത്തിയത്. ഇപ്പോഴും ആ നിമിഷങ്ങൾ ഓർക്കുമ്പോൾ ഉള്ളിൽ ഒരു വിറയൽ തോന്നും. ചുറ്റും ഇരുപത് മൃതദേഹങ്ങൾ കിടക്കുമ്പോൾ, ആരുടെയോ കൈകൾ നിങ്ങളുടെ കാലിൽ തട്ടുന്നത് അനുഭവപ്പെടുമ്പോൾ, ഒരു നിഷ്പക്ഷ നിരീക്ഷകനായി നിന്ന് ആ ദൃശ്യങ്ങൾ പകർത്തുക എന്നത് ഒട്ടും എളുപ്പമല്ല. അത് ആരുടെ ബന്ധുവാണെന്നോ, അവരുടെ കുടുംബത്തിന് അവരെ ലഭിക്കുമോ എന്നതിനെക്കുറിച്ചോ നിങ്ങൾക്ക് ചിന്തിക്കാൻ കഴിയില്ല. നിങ്ങളുടെ ജോലി മാത്രമേ ചെയ്യാൻ സാധിക്കൂ. ആ മൂന്ന് നാല് ദിവസങ്ങൾ ഒരിക്കലും മറക്കാൻ കഴിയില്ല.`,
    
    "pullquote-3": `"ചുറ്റും ഇരുപത് മൃതദേഹങ്ങൾ കിടക്കുമ്പോൾ, ഒരു നിഷ്പക്ഷ നിരീക്ഷകനായി നിന്ന് ആ ദൃശ്യങ്ങൾ പകർത്തുക എന്നത് ഒട്ടും എളുപ്പമല്ല."`,
    
    "theme-4": `IV. വെളിച്ചത്തിന്റെ തത്ത്വചിന്ത <span>അഹംഭാവം, ശാസ്ത്രം & ഡിജിറ്റൽ യുഗം</span>`,
    "q8": `Q: ഫോട്ടോഗ്രാഫി ഒരു കലയും ശാസ്ത്രവുമാണ്. താങ്കൾ അതിനെ എങ്ങനെയാണ് കാണുന്നത്?`,
    "a8": `A: ഞാൻ ഒരു ശരാശരി വിദ്യാർത്ഥിയായിരുന്നു, ശാസ്ത്രം ഒരിക്കലും എന്റെ മനസ്സിൽ തങ്ങിനിന്നിരുന്നില്ല. അതുകൊണ്ട് ഫോട്ടോഗ്രാഫിയെ ഒരു കലയായി കാണാനേ എനിക്ക് കഴിയൂ. അതൊരു മനോഹരമായ കലയാണ്. അതിലൂടെ എനിക്ക് ഒരുപാട് കാര്യങ്ങൾ ലഭിച്ചു — സാമൂഹികമായും സാമ്പത്തികമായും, അതിലുപരി വ്യക്തിപരമായ വളർച്ചയുടെ കാര്യത്തിലും. താമരയെപ്പോലെ നിർമമതയോടെ ജോലി ചെയ്യാൻ ഫോട്ടോഗ്രാഫി എന്നെ പഠിപ്പിച്ചു. ഞാൻ എന്താണോ അത് തന്നെയായി തുടരാൻ അത് എന്നെ പഠിപ്പിച്ചു.
    <br><br>
    മുൻപ് ഞാൻ മനോഹരമായ ഒരു सूर्यോദയത്തിന്റെയോ സൂര്യാസ്തമയത്തിന്റെയോ അല്ലെങ്കിൽ ലാൻഡ്‌സ്‌കേപ്പിന്റെയോ ചിത്രവുമായി വരുമ്പോൾ ഉള്ളിൽ ഒരു അഭിമാനം തോന്നിയിരുന്നു — ഞാൻ അസാധാരണമായ എന്തോ ഒന്ന് സൃഷ്ടിച്ചുവെന്നും എനിക്ക് വലിയ കലാവാസനയുണ്ടെന്നും. എന്നാൽ പിന്നീട് എനിക്ക് മനസ്സിലായി, ആർക്കും മനോഹരമായ ഒരു സൂര്യോദയത്തിന്റെയോ സൂര്യാസ്തമയത്തിന്റെയോ ഫോട്ടോ എടുക്കാൻ കഴിയുമെന്ന്. അതിൽ വലിയ കാര്യമൊന്നുമില്ല. അവിടെയുണ്ടാകാൻ എനിക്ക് അവസരം ലഭിച്ചു എന്നതാണ് എന്റെ ഭാഗ്യം. ഞാൻ അസമിലും ഹിമാലയത്തിലും പോയിട്ടുണ്ട്, പലർക്കും എത്തിപ്പെടാൻ കഴിയാത്ത സ്ഥലങ്ങളിൽ.
    <br><br>
    ഞാൻ കൊണ്ടുവരുന്ന ഫോട്ടോകൾ ഒരു മാധ്യമം മാത്രമാണ്. ആ അർത്ഥത്തിൽ ഞാൻ ഒരു ദൂതൻ മാത്രമാണ്, ഒരു കത്ത് കൊണ്ടുപോകുന്നതിൽ ഒരു ദൂതന് അഹംഭാവം തോന്നേണ്ട കാര്യമില്ല. ഒരു ഫോട്ടോഗ്രാഫർ എന്ന നിലയിൽ ഞാൻ വെറുമൊരു മാധ്യമമാണ്. സൂര്യോദയവും സൂര്യാസ്തമയവും അവയിൽത്തന്നെ മനോഹരമാണ്. ആ തിരിച്ചറിവ് എന്നിലെ ദർശകനെ ശക്തനാക്കി. എന്നിൽ എപ്പോഴെങ്കിലും ഉണ്ടായിരുന്ന അഹംഭാവമെല്ലാം പതുക്കെ ഇല്ലാതായി. ഇന്ന് എന്റെ വിദ്യാർത്ഥികൾ — പതിനാറോ പതിനേഴോ വയസ്സുള്ള കുട്ടികൾ — അവരുടെ ഫോട്ടോകൾ കൊണ്ടുവരുമ്പോൾ, അവർക്ക് തോന്നുന്ന അതേ ജിജ്ഞാസയും അത്ഭുതവും എനിക്കും തോന്നാറുണ്ട്. ആ അത്ഭുതബോധം എന്നെ ഒരിക്കലും വിട്ടുപോയിട്ടില്ല.`,
    
    "q9": `Q: സാങ്കേതികവിദ്യ ഫോട്ടോഗ്രാഫിയെ വളരെ ലളിതമാക്കിയോ, ഇപ്പോൾ ആർക്കും നല്ലൊരു ചിത്രം എടുക്കാൻ സാധിക്കുമോ?`,
    "a9": `A: അതെ, അത് വളരെ ശരിയാണ്. ഇന്നത്തെ ഡിജിറ്റൽ യുഗത്തിൽ മോശമൊരു ഫോട്ടോ എടുക്കണമെങ്കിൽ പോലും കഠിനാധ്വാനം ചെയ്യേണ്ട അവസ്ഥയാണ്. ക്യാമറകൾ അത്രയധികം അത്യാധുനികമാണ്, അതുകൊണ്ട് തന്നെ ഫോട്ടോകൾ സ്വാഭാവികമായും മനോഹരമായി വരുന്നു. സാങ്കേതികവിദ്യ ഈ മാധ്യമത്തെ പൂർണ്ണമായും മാറ്റിമറിച്ചു. മുൻപ് ഫിലിം ഉണ്ടായിരുന്നു, ഫിലിമിനോടൊപ്പം വ്യത്യസ്ത സ്പീഡുകൾ, ലോഡിംഗ്, ഷൂട്ടിംഗ്, ഡെവലപ്പിംഗ്, ഒടുവിൽ പ്രിന്റ് ചെയ്ത ഫോട്ടോ കൈയിൽ പിടിക്കുന്നത് വരെയുള്ള കാര്യങ്ങൾ. ഡിജിറ്റൽ സാങ്കേതികവിദ്യ വന്നതോടെ അതെല്ലാം ഇല്ലാതായി.
    <br><br>
    ആദ്യത്തെ മാറ്റം ഫോട്ടോഗ്രാഫിക്ക് ചിലവ് കുറഞ്ഞു എന്നതാണ്. 1989-ലോ 1990-ലോ മുപ്പത്തിയാറ് ഫ്രെയിമുള്ള ഒരു ഫിലിം റോൾ ഉപയോഗിച്ചാൽ, പ്രിന്റ് തിരികെ വരുമ്പോഴേക്കും എഴുന്നൂറോ എണ്ണൂറോ രൂപ ചിലവാകുമായിരുന്നു. ഒരു ഫോട്ടോഗ്രാഫി വിദ്യാർത്ഥിയെ സംബന്ധിച്ച് അത് വലിയൊരു തുകയായിരുന്നു. ഇന്ന് നിങ്ങൾക്ക് ഫോട്ടോകൾ ഉടനടി കമ്പ്യൂട്ടറിൽ കാണാൻ കഴിയും, അതിനാൽ ഈ പ്രക്രിയ എളുപ്പവും ചിലവ് കുറഞ്ഞതുമാണ്. പുതിയ തരം ലെൻസുകൾ ജോലിയെ കൂടുതൽ ലളിതമാക്കി. പിന്നീട് ഇന്റർനെറ്റ് വന്നതോടെ ഫോട്ടോകൾ അയക്കുന്നതും വളരെ എളുപ്പമായി. എനിക്ക് നിമിഷങ്ങൾക്കകം ഒരു ചിത്രം നിങ്ങൾക്ക് അയച്ചുതരാൻ കഴിയും.
    <br><br>
    അങ്ങനെ ഫോട്ടോഗ്രാഫി ഫോട്ടോഗ്രാഫർമാർക്ക് കൂടുതൽ എളുപ്പമായി, എന്നാൽ അതേസമയം മത്സരം വളരെ കഠിനമായതിനാൽ നിങ്ങളുടെ കഴിവ് തെളിയിക്കുക എന്നത് കൂടുതൽ ബുദ്ധിമുട്ടേറിയതായി മാറി. ഇന്ന് ആർക്കും നല്ല ഫോട്ടോകൾ എടുക്കാം. പലർക്കും ഫേസ്ബുക്കിലും ഇൻസ്റ്റാഗ്രാമിലും മറ്റ് പ്ലാറ്റ്‌ഫോമുകളിലും ആകർഷകമായ ചിത്രങ്ങൾ പോസ്റ്റ് ചെയ്യാൻ സാധിക്കും. ഒരു "നല്ല ഫോട്ടോഗ്രാഫർക്ക്" ഉണ്ടായിരുന്ന കുത്തക ഇപ്പോൾ ഇല്ലാതായി. എല്ലാ ദിവസവും നിങ്ങൾ സ്വയം തെളിയിക്കേണ്ടതുണ്ട്.`,
    
    "q10": `Q: ശാസ്ത്രത്തിന്റെ പുരോഗതി കലയുടെ പതുക്കെയുള്ള മരണത്തിന് കാരണമായോ?`,
    "a10": `A: ഇല്ല, ഞാൻ അതിനോട് യോജിക്കുന്നില്ല. അവസാനം അത് ഗുജറാത്തിയിലെ ഒരു പഴഞ്ചൊല്ല് പോലെയാണ്: "കിണറ്റിൽ വെള്ളമുണ്ടെങ്കിൽ അത് തൊട്ടിയിലുമെത്തും." അതായത്, യഥാർത്ഥ ഫോട്ടോ ശക്തമാണെങ്കിൽ മാത്രമേ എഡിറ്റിംഗിന് അതിനെ സഹായിക്കാൻ കഴിയൂ. അടിസ്ഥാന ചിത്രം മോശമാണെങ്കിൽ ഒന്നിനും അതിനെ രക്ഷിക്കാൻ കഴിയില്ല. ഫോട്ടോഷോപ്പും മറ്റ് എഡിറ്റിംഗ് ടൂളുകളും ആഭരണങ്ങളും മേക്കപ്പും പോലെയുള്ള വെറും ബാഹ്യമായ കാര്യങ്ങൾ മാത്രമാണ്.
    <br><br>
    ഒരു വധു മനോഹരമായി വസ്ത്രം ധരിച്ച് വലിയ രീതിയിൽ മേക്കപ്പും ആഭരണങ്ങളും അണിഞ്ഞിട്ടുണ്ടാകാം, എന്നാൽ അവളുടെ സ്വാഭാവിക ഭംഗിയേക്കാൾ വലുതല്ല ഇതൊന്നും. അവൾക്ക് അടിസ്ഥാനപരമായി ഭംഗിയുണ്ടെങ്കിൽ മേക്കപ്പില്ലാതെയും അവൾ സുന്ദരിയായിരിക്കും. മേക്കപ്പില്ലാത്ത മുഖവും മനോഹരമായ ഒരു മുഖമായിരിക്കാം.`,
    
    "pullquote-4": `"ഒരു കത്ത് കൊണ്ടുപോകുന്നതിൽ ഒരു ദൂതന് അഹംഭാവം തോന്നേണ്ട കാര്യമില്ല. ഒരു ഫോട്ടോഗ്രാഫർ എന്ന നിലയിൽ ഞാൻ വെറുമൊരു മാധ്യമമാണ്."`,
    
    "theme-5": `V. കൈമാറുന്ന വെളിച്ചം <span>പഠിപ്പിക്കൽ, സംഗീതം & ക്രിയേറ്റീവ് യാത്രകൾ</span>`,
    "q11": `Q: താങ്കൾ ഫോട്ടോഗ്രാഫി പഠിപ്പിക്കുകയും വർക്ക്‌ഷോപ്പുകൾ നടത്തുകയും ചെയ്യുന്നുണ്ട്. ഈ കല എത്രത്തോളം പഠിപ്പിക്കാൻ കഴിയും?`,
    "a11": `A: ഇപ്പോൾ ഇത് വളരെ മെച്ചപ്പെട്ടിട്ടുണ്ട്. ഞങ്ങളുടെ കാലത്ത് ഫോട്ടോഗ്രാഫി പഠിപ്പിക്കുന്ന സ്ഥാപനങ്ങൾ ഉണ്ടായിരുന്നില്ല. ഇന്ന് പല കോളേജുകളിലും ഇൻസ്റ്റിറ്റ്യൂട്ടുകളിലും ഇതുണ്ട്. പുതിയ ഉപകരണങ്ങൾ വന്നതോടെ പഠിപ്പിക്കലും എളുപ്പമായി. എന്നാൽ ഫോട്ടോഗ്രാഫി ഒരിക്കലും അടച്ചിട്ട മുറികളിലോ ക്ലാസ് മുറികളിലോ മാത്രം പഠിക്കാൻ കഴിയില്ലെന്നാണ് എനിക്ക് തോന്നിയിട്ടുള്ളത്. ഞാൻ കോളേജുകളിൽ പഠിപ്പിക്കുന്നുണ്ട്, എന്നാൽ ആദ്യത്തെ മൂന്നോ നാലോ ക്ലാസുകൾക്ക് ശേഷം ഞാൻ വിദ്യാർത്ഥികളെ പുറത്തേക്ക് കൊണ്ടുപോകും. ഞങ്ങൾ പോണ്ടിച്ചേരി, അസം, ഹിമാലയം തുടങ്ങിയ സ്ഥലങ്ങളിൽ പോയി അവിടെ വർക്ക്‌ഷോപ്പുകൾ നടത്താറുണ്ട്.
    <br><br>
    വിദ്യാർത്ഥികൾക്ക് ധാരാളം തെറ്റുകൾ വരുത്താൻ അനുവാദം നൽകണമെന്നാണ് എന്റെ വ്യക്തിപരമായ വിശ്വാസം. ധാരാളം തെറ്റുകൾ വരുത്താനും അതിൽ നിന്ന് പഠിക്കാനും ഞാൻ അവരോട് പറയാറുണ്ട്. ലാൻഡ്‌സ്‌കേപ്പ് ഫോട്ടോഗ്രാഫി തെറ്റുകൾ ഉടനടി കാണിച്ചുതരുന്ന ഒരു മേഖലയാണ്. തെറ്റ് ആ പ്രകൃതിദൃശ്യത്തിലല്ല, മറിച്ച് നിങ്ങൾ അത് എങ്ങനെ ചിത്രീകരിക്കുന്നു എന്നതിലാണ്. നിങ്ങൾ അത് ശരിയായി ചെയ്തില്ലെങ്കിൽ ആ തെറ്റ് വ്യക്തമായി കാണാം. അങ്ങനെയാണ് ഒരാൾ പഠിക്കുന്നത് — സ്വന്തം തെറ്റുകൾ വ്യക്തമായി മനസ്സിലാക്കിക്കൊണ്ട്. ഓരോ വ്യക്തിയിലും ഒരു ഫോട്ടോഗ്രാഫർ ഉണ്ടെന്നാണ് ഞാൻ വിശ്വസിക്കുന്നത്. ഉള്ളിലെ ആ ഫോട്ടോഗ്രാഫർക്ക് നിങ്ങൾ എത്രത്തോളം അവസരം നൽകുന്നു എന്നതാണ് യഥാർത്ഥ ചോദ്യം.`,
    
    "q12": `Q: സഞ്ജയ്, ഫോട്ടോഗ്രാഫിക്ക് പുറമെ താങ്കളുടെ മറ്റ് താല്പര്യങ്ങൾ എന്തൊക്കെയാണ്?`,
    "a12": `A: എനിക്ക് വായന വളരെ ഇഷ്ടമാണ്. എന്നെ സംബന്ധിച്ച് വായന ശ്വസിക്കുന്നത് പോലെയാണ്. എനിക്ക് വായിക്കാതിരിക്കാൻ കഴിയില്ല. എനിക്ക് നല്ല സംഗീതവും വളരെ ഇഷ്ടമാണ്. വായനയും സംഗീതവുമില്ലാതെ എനിക്ക് മുന്നോട്ട് പോകാൻ കഴിയില്ല. എനിക്ക് ഇവ രണ്ടിനോടും വലിയ താല്പര്യമാണ്, ഒരുപക്ഷേ അതുകൊണ്ടായിരിക്കാം എനിക്ക് നല്ലൊരു എഴുത്തുകാരനോ സംഗീതജ്ഞനോ ആകാൻ കഴിയാതിരുന്നത് — കാരണം ഞാൻ പുസ്തകങ്ങളുടെയും സംഗീതത്തിന്റെയും പൂർണ്ണ സമയ ആരാധകനാണ്. ഞാൻ കഥകളും നോവലുകളും ഉപന്യാസങ്ങളും കത്തുകളും കവിതകളും അങ്ങനെ എല്ലാം വായിക്കാറുണ്ട്. എല്ലാ ഭാഷകളിലുമുള്ള പുസ്തകങ്ങൾ ഞാൻ വായിക്കും.
    <br><br>
    സംഗീതത്തിൽ ഞാൻ ഇന്ത്യൻ ക്ലാസിക്കൽ സംഗീതമാണ് കൂടുതൽ ഇഷ്ടപ്പെടുന്നത്, എങ്കിലും എനിക്ക് ഒരു റോക്ക് ബാൻഡിനോട് എതിർപ്പൊന്നുമില്ല. എനിക്ക് മനസ്സിലാക്കാൻ കഴിയുന്നത്രയും ഞാൻ റോക്ക് സംഗീതവും ആസ്വദിക്കാറുണ്ട്. എന്റെ മകൻ റോക്ക്, ജാസ് ബാൻഡുകളിൽ പ്രവർത്തിക്കുന്നുണ്ട്, അവൻ എനിക്ക് കാര്യങ്ങൾ വിശദീകരിച്ചു തരുമ്പോഴും എന്നെ പഠിപ്പിക്കുമ്പോഴും അതെല്ലാം എനിക്ക് വളരെ ഇഷ്ടമാണ്. സംഗീതത്തിന്റെ എല്ലാ രൂപങ്ങളെയും ഞാൻ ബഹുമാനിക്കുന്നു, എങ്കിലും എനിക്ക് കൂടുതൽ മനസ്സിലാക്കാൻ കഴിയുന്നത് ഇന്ത്യൻ ക്ലാസിക്കൽ സംഗീതമായതുകൊണ്ട് അത് എന്നെ കുറച്ചുകൂടി ആകർഷിക്കുന്നു.`,
    
    "q13": `Q: താങ്കൾ നമ്മുടെ പല പ്രഗത്ഭരായ സംഗീതജ്ഞരുടെയും ചിത്രങ്ങൾ പകർത്തിയിട്ടുണ്ടല്ലോ. ആ അനുഭവം എങ്ങനെയായിരുന്നു?`,
    "a13": `A: അതെ, ഞാൻ ഏതാണ്ട് എല്ലാ പ്രമുഖ ഇന്ത്യൻ ക്ലാസിക്കൽ സംഗീതജ്ഞരുടെയും ഫോട്ടോകൾ എടുത്തിട്ടുണ്ട്. എന്നാൽ സത്യം പറഞ്ഞാൽ, എനിക്ക് സംഗീതം അറിയാത്തതിനാൽ എപ്പോഴും ഉള്ളിൽ എന്തോ ഒരു കുറവ് തോന്നിയിരുന്നു. ആ കലാകാരന്മാരുടെ ഏറ്റവും മികച്ച നിമിഷങ്ങൾ പകർത്തിക്കൊണ്ട് ആ കുറവ് നികത്താനാണ് ഞാൻ ശ്രമിച്ചത്.
    <br><br>
    ഒരു തരത്തിൽ, എനിക്കില്ലാത്ത ഒരു കാര്യത്തിന് പകരമായി എന്റെ ജോലി വളരെ ശ്രദ്ധയോടും മനോഹരമായും ചെയ്യാൻ ഞാൻ ആഗ്രഹിച്ചു. എനിക്ക് സംഗീതം അറിയാത്തതിനാൽ, ആ സംഗീതജ്ഞൻ എന്നെ ഓർക്കാൻ തക്കതായ എന്തെങ്കിലും ഞാൻ ചെയ്യണമെന്ന് എനിക്ക് തോന്നി. അതുകൊണ്ട് പണ്ഡിറ്റ് ശിവകുമാർ ശർമ്മയോ ഉസ്താദ് സക്കീർ ഹുസൈനോ എന്നെ വിളിച്ച് "ഫോട്ടോ വളരെ നന്നായി വന്നിട്ടുണ്ട് — അത് ഞങ്ങൾക്ക് തരുമോ" എന്ന് ചോദിക്കുമ്പോൾ, ഞാൻ ഒരു മനോഹരമായ രാഗം പഠിച്ചതുപോലെയാണ് എനിക്ക് അനുഭവപ്പെടാറുള്ളത്.`,
    
    "q14": `Q: സഞ്ജയ്, താങ്കൾ ഇന്ന് ഒരു പ്രശസ്ത ഫോട്ടോഗ്രാഫർ ആയിരുന്നില്ലെങ്കിൽ എന്താകുമായിരുന്നു എന്ന് കരുതുന്നു?`,
    "a14": `A: ഞാൻ ഒരു അധ്യാപകനാകുമായിരുന്നു എന്നാണ് കരുതുന്നത്. എനിക്ക് ഇപ്പോൾ അങ്ങനെയാണ് തോന്നുന്നത്, കാരണം കഴിഞ്ഞ കുറേ വർഷങ്ങളായി ഞാൻ അധ്യാപന രംഗത്തുണ്ട്. ഒരു അധ്യാപകനായിരിക്കുക, ഒരു വഴികാട്ടിയായിരിക്കുക — പ്രത്യേകിച്ചും എനിക്ക് 60 വയസ്സാകാറായ ഈ സമയത്ത് — അത് നൽകുന്ന സംതൃപ്തി വളരെ വലുതാണ്. ഞാൻ ഫോട്ടോ എടുക്കുന്നില്ലായിരുന്നെങ്കിൽ തീർച്ചയായും ഒരു അധ്യാപകനാകുമായിരുന്നു.
    <br><br>
    കുട്ടികളുടെ കൂടെയായിരിക്കാനും അവരുടെ ഊർജ്ജസ്വലതയും പുതുമയും ആസ്വദിക്കാനും ഞാൻ ഇഷ്ടപ്പെടുന്നു. വർഷങ്ങളോളം ഇന്ത്യയിൽ ജീവിച്ച അമേരിക്കൻ ആർക്കിടെക്റ്റും ഞങ്ങളുടെ മുതിർന്ന ഫാക്കൽറ്റിയുമായ ക്രിസ്റ്റഫർ ബെനിഞ്ചർ ഒരിക്കൽ ഞങ്ങളെ മനോഹരമായ ഒരു കാര്യം പഠിപ്പിച്ചു: "നിങ്ങളുടെ വിദ്യാർത്ഥിക്ക് നൽകാൻ കഴിയുന്ന ഏറ്റവും വലിയ സമ്മാനം അവനെ എപ്പോഴും ഒരു വിദ്യാർത്ഥിയായിരിക്കാൻ പഠിപ്പിക്കുക എന്നതാണ്." ആ വരികൾ എന്റെ ഉള്ളിൽ തങ്ങിനിൽക്കുന്നുണ്ട്. അത് വളരെ പ്രചോദനകരമാണ്. ഞാൻ പഠിപ്പിക്കാൻ പോയിക്കഴിഞ്ഞാൽ രണ്ട് മൂന്ന് മണിക്കൂർ കഴിഞ്ഞ് മടങ്ങിവരുമ്പോൾ എനിക്ക് ഒട്ടും ക്ഷീണം തോന്നാറില്ല. ഞാനും രണ്ട് പുതിയ കാര്യങ്ങൾ പഠിച്ച് വലിയൊരു ഊർജ്ജത്തോടെയാണ് മടങ്ങിവരുന്നത്. അതാണ് എന്നെ മുന്നോട്ട് നയിക്കുന്നത്.`,
    
    "pullquote-5": `"നിങ്ങളുടെ വിദ്യാർത്ഥിക്ക് നൽകാൻ കഴിയുന്ന ഏറ്റവും വലിയ സമ്മാനം അവനെ എപ്പോഴും ഒരു വിദ്യാർത്ഥിയായിരിക്കാൻ പഠിപ്പിക്കുക എന്നതാണ്."`
  }
};

// Original English text backup to restore
const originalEnglishText = {};

// When DOM is ready
$(document).ready(function() {
  // Store all original English texts
  $('[data-translate]').each(function() {
    const key = $(this).attr('data-translate');
    originalEnglishText[key] = $(this).html().trim();
  });

  // Listen to selector change
  $('#interview-lang-selector').on('change', function() {
    const lang = $(this).val();
    
    // Add premium fade-out effect during transition
    $('[data-translate]').animate({ opacity: 0 }, 250, function() {
      const key = $(this).attr('data-translate');
      
      // Update HTML content based on selected language
      if (lang === 'en') {
        $(this).html(originalEnglishText[key]);
      } else if (interviewTranslations[lang] && interviewTranslations[lang][key]) {
        $(this).html(interviewTranslations[lang][key]);
      }
      
      // Premium fade-in effect after replacement
      $(this).animate({ opacity: 1 }, 250);
    });
  });
});
